CREATE OR REPLACE FUNCTION public.jxc_ap_balance_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE cid bigint; bid bigint; fid bigint; ft text; actual numeric; projection numeric; tab text;
BEGIN
 cid:=NEW.country_id;
 IF TG_TABLE_NAME='ap_settlement_line' THEN bid:=NEW.bill_id;fid:=NEW.from_id;ft:=NEW.from_type;
 ELSIF TG_TABLE_NAME='ap_bill' THEN bid:=NEW.id;
 ELSE fid:=NEW.id;ft:=CASE TG_TABLE_NAME WHEN 'ap_payment' THEN 'PAYMENT' WHEN 'ap_prepayment' THEN 'PREPAYMENT' ELSE 'CREDIT_NOTE' END;END IF;
 IF bid IS NOT NULL THEN
  SELECT coalesce(sum(l.bill_amount*s.direction),0) INTO actual FROM ap_settlement_line l JOIN ap_settlement s ON s.country_id=l.country_id AND s.id=l.settlement_id WHERE l.country_id=cid AND l.bill_id=bid;
  SELECT paid_amount INTO projection FROM ap_bill WHERE country_id=cid AND id=bid;
  IF actual IS DISTINCT FROM projection THEN RAISE EXCEPTION 'AP_BILL_BALANCE_INCONSISTENT' USING ERRCODE='23514';END IF;
 END IF;
 IF fid IS NOT NULL THEN
  tab:=CASE ft WHEN 'PAYMENT' THEN 'ap_payment' WHEN 'PREPAYMENT' THEN 'ap_prepayment' ELSE 'ap_credit_note' END;
  SELECT coalesce(sum(l.from_amount*s.direction),0) INTO actual FROM ap_settlement_line l JOIN ap_settlement s ON s.country_id=l.country_id AND s.id=l.settlement_id WHERE l.country_id=cid AND l.from_type=ft AND l.from_id=fid;
  EXECUTE format('SELECT used_amount FROM %I WHERE country_id=$1 AND id=$2',tab) INTO projection USING cid,fid;
  IF actual IS DISTINCT FROM projection THEN RAISE EXCEPTION 'AP_SOURCE_BALANCE_INCONSISTENT' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_claim_balance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE sign integer; c bigint; t text; s bigint; q numeric; a numeric;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'AP_CLAIM_APPEND_ONLY'; END IF;
 IF TG_OP='UPDATE' AND NOT OLD.effective AND NEW.effective THEN RAISE EXCEPTION 'AP_CLAIM_REACTIVATION_FORBIDDEN';END IF;
 IF TG_OP='UPDATE' AND (NEW.country_id,NEW.bill_id,NEW.bill_line_id,NEW.source_type,NEW.source_id,NEW.qty,NEW.amount) IS DISTINCT FROM (OLD.country_id,OLD.bill_id,OLD.bill_line_id,OLD.source_type,OLD.source_id,OLD.qty,OLD.amount) THEN RAISE EXCEPTION 'AP_CLAIM_IDENTITY_IMMUTABLE'; END IF;
 sign := CASE WHEN TG_OP='INSERT' AND NEW.effective THEN 1 WHEN TG_OP='UPDATE' AND OLD.effective AND NOT NEW.effective THEN -1 WHEN TG_OP='UPDATE' AND NOT OLD.effective AND NEW.effective THEN 1 ELSE 0 END;
 IF sign<>0 THEN UPDATE ap_source_capacity SET claimed_qty=claimed_qty+sign*NEW.qty,claimed_amount=claimed_amount+sign*NEW.amount,version=version+1 WHERE country_id=NEW.country_id AND source_type=NEW.source_type AND source_id=NEW.source_id; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_claim_release_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE target_bill_id bigint; bill_status text;
BEGIN
 target_bill_id:=(to_jsonb(NEW)->>CASE WHEN TG_TABLE_NAME='ap_bill' THEN 'id' ELSE 'bill_id' END)::bigint;
 SELECT status INTO bill_status FROM ap_bill WHERE country_id=NEW.country_id AND id=target_bill_id;
 IF (bill_status<>'VOIDED' AND EXISTS(SELECT 1 FROM ap_source_claim WHERE country_id=NEW.country_id AND ap_source_claim.bill_id=target_bill_id AND NOT effective)) OR (bill_status='VOIDED' AND EXISTS(SELECT 1 FROM ap_source_claim WHERE country_id=NEW.country_id AND ap_source_claim.bill_id=target_bill_id AND effective)) THEN
  RAISE EXCEPTION 'AP_CLAIM_RELEASE_REQUIRES_VOID' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_cost_assignment_final()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE selected_value jsonb;selected_assignment bigint;parent ap_cost_assignment;total_qty numeric;line_count bigint;
BEGIN
 selected_value:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 selected_assignment:=(selected_value->>CASE WHEN TG_TABLE_NAME='ap_cost_assignment' THEN 'id' ELSE 'assignment_id' END)::bigint;
 SELECT * INTO parent FROM ap_cost_assignment WHERE country_id=(selected_value->>'country_id')::bigint AND id=selected_assignment;
 IF parent.id IS NULL THEN RETURN NULL;END IF;
 IF parent.status='DRAFT' THEN
  IF EXISTS(SELECT 1 FROM ap_cost_assignment_line WHERE country_id=parent.country_id AND assignment_id=parent.id AND (principal_amount IS NOT NULL OR economic_basis IS NOT NULL)) THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_STATE_INVALID';END IF;
  RETURN NULL;
 END IF;
 SELECT count(*),coalesce(sum(base_qty),0) INTO line_count,total_qty FROM ap_cost_assignment_line WHERE country_id=parent.country_id AND assignment_id=parent.id;
 IF line_count=0 OR total_qty IS DISTINCT FROM (parent.source_basis->>'qty')::numeric
  OR EXISTS(SELECT 1 FROM ap_cost_assignment_line WHERE country_id=parent.country_id AND assignment_id=parent.id AND (principal_amount IS NULL OR economic_basis IS NULL))
  OR NOT EXISTS(SELECT 1 FROM fin_event_result r JOIN sys_biz_event e ON e.country_id=r.country_id AND e.book_id=r.book_id AND e.id=r.event_id
   JOIN sys_biz_event_consume c ON c.country_id=e.country_id AND c.book_id=e.book_id AND c.event_id=e.id
   WHERE r.country_id=parent.country_id AND r.book_id=parent.book_id AND r.event_id=parent.frozen_event_id AND r.status IN('GENERATED','NO_VOUCHER')
    AND e.event_type='CST_INBOUND_COST_CONFIRMED' AND e.source_type='CST_INBOUND_COST' AND e.source_id=parent.cost_id
    AND c.consumer='FIN_VOUCHER' AND c.status IN('PROCESSING','DONE') AND c.xmin::text::numeric=mod(pg_current_xact_id()::text::numeric,4294967296)) THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_RESULT_REQUIRED';END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_cost_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE selected_value jsonb;expected_basis jsonb;
BEGIN
 selected_value:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 PERFORM jxc_ap_cost_basis_lock((selected_value->>'country_id')::bigint,(selected_value->>'book_id')::bigint);
 expected_basis:=jxc_ap_cost_source_basis((selected_value->>'country_id')::bigint,(selected_value->>'book_id')::bigint,(selected_value->>'cost_id')::bigint);
 IF expected_basis IS NULL OR selected_value->'source_basis' IS DISTINCT FROM expected_basis THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_SOURCE_CHANGED';END IF;
 PERFORM jxc_assert_period_open((selected_value->>'country_id')::bigint,(selected_value->>'book_id')::bigint,(expected_basis->>'confirmedBizDate')::date);
 IF EXISTS(SELECT 1 FROM fin_event_result r JOIN sys_biz_event e ON e.country_id=r.country_id AND e.id=r.event_id WHERE e.country_id=(selected_value->>'country_id')::bigint AND e.book_id=(selected_value->>'book_id')::bigint AND e.source_type='CST_INBOUND_COST' AND e.source_id=(selected_value->>'cost_id')::bigint AND e.event_type='CST_INBOUND_COST_CONFIRMED') THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_LEGACY_RESULT';END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'DRAFT' OR NEW.version<>0 THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_STATE_INVALID';END IF;
  RETURN NEW;
 END IF;
 IF OLD.status='FROZEN' THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_IMMUTABLE';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 IF (to_jsonb(NEW)-ARRAY['status','version','frozen_event_id','frozen_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','frozen_event_id','frozen_at']) OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_IMMUTABLE';END IF;
 IF NEW.status='FROZEN' AND NOT jxc_ap_cost_current_intent(NEW.country_id,NEW.book_id,NEW.cost_id,NEW.frozen_event_id) THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_INTENT_REQUIRED';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_cost_assignment_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE selected_value jsonb;parent ap_cost_assignment;parent_xid numeric;cost cst_inbound_cost;bill ap_bill;bill_line ap_bill_line;claim ap_source_claim;expected_basis jsonb;used_qty numeric;selected_line bigint;
BEGIN
 selected_value:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 PERFORM jxc_ap_cost_basis_lock((selected_value->>'country_id')::bigint,(selected_value->>'book_id')::bigint);
 SELECT * INTO parent FROM ap_cost_assignment WHERE country_id=(selected_value->>'country_id')::bigint AND book_id=(selected_value->>'book_id')::bigint AND id=(selected_value->>'assignment_id')::bigint FOR UPDATE;
 SELECT xmin::text::numeric INTO parent_xid FROM ap_cost_assignment WHERE country_id=parent.country_id AND id=parent.id;
 IF parent.id IS NULL OR parent.cost_id IS DISTINCT FROM (selected_value->>'cost_id')::bigint THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_SOURCE_INVALID';END IF;
 IF parent.status='DRAFT' AND EXISTS(SELECT 1 FROM fin_event_result r JOIN sys_biz_event e ON e.country_id=r.country_id AND e.id=r.event_id WHERE e.country_id=parent.country_id AND e.book_id=parent.book_id AND e.source_type='CST_INBOUND_COST' AND e.source_id=parent.cost_id AND e.event_type='CST_INBOUND_COST_CONFIRMED') THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_LEGACY_RESULT';END IF;
 IF TG_OP='DELETE' THEN
  IF parent.status<>'DRAFT' THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_IMMUTABLE';END IF;
  PERFORM jxc_assert_period_open(parent.country_id,parent.book_id,(parent.source_basis->>'confirmedBizDate')::date);
  RETURN OLD;
 END IF;
 IF TG_OP='INSERT' THEN
  IF parent.status<>'DRAFT' OR NEW.principal_amount IS NOT NULL OR NEW.economic_basis IS NOT NULL THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_STATE_INVALID';END IF;
 ELSE
  IF parent.status<>'FROZEN' OR parent_xid<>mod(pg_current_xact_id()::text::numeric,4294967296)
    OR OLD.principal_amount IS NOT NULL OR OLD.economic_basis IS NOT NULL OR NEW.principal_amount IS NULL OR NEW.economic_basis IS NULL
    OR (to_jsonb(NEW)-ARRAY['principal_amount','economic_basis']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['principal_amount','economic_basis'])
    OR NOT jxc_ap_cost_current_intent(parent.country_id,parent.book_id,parent.cost_id,parent.frozen_event_id) THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_IMMUTABLE';END IF;
 END IF;
 SELECT * INTO cost FROM cst_inbound_cost WHERE country_id=NEW.country_id AND book_id=NEW.book_id AND id=NEW.cost_id;
 SELECT * INTO bill FROM ap_bill WHERE country_id=NEW.country_id AND book_id=NEW.book_id AND id=NEW.bill_id FOR UPDATE;
 SELECT * INTO bill_line FROM ap_bill_line WHERE country_id=NEW.country_id AND bill_id=NEW.bill_id AND id=NEW.bill_line_id FOR UPDATE;
 SELECT * INTO claim FROM ap_source_claim WHERE country_id=NEW.country_id AND bill_id=NEW.bill_id AND bill_line_id=NEW.bill_line_id AND source_type='PUR_ORDER_LINE_BASE' AND source_id=NEW.canonical_source_id AND effective FOR UPDATE;
 IF bill.id IS NULL OR bill_line.id IS NULL OR claim.id IS NULL OR bill.status NOT IN('CONFIRMED','PARTIAL_PAID','PAID') OR bill.valuation_status<>'READY'
  OR bill.partner_type<>'SUPPLIER' OR bill.bill_type<>'PURCHASE' OR bill.currency IS DISTINCT FROM cost.src_currency OR bill.base_currency IS DISTINCT FROM cost.base_currency
  OR bill.rate IS NULL OR parent.source_basis->>'rate' IS NULL OR bill.rate IS DISTINCT FROM (parent.source_basis->>'rate')::numeric
  OR bill.partner_id IS DISTINCT FROM (SELECT supplier_id FROM pur_order WHERE country_id=cost.country_id AND id=cost.po_id)
  OR bill_line.product_id IS DISTINCT FROM cost.product_id OR bill_line.canonical_source_type IS DISTINCT FROM NEW.canonical_source_type OR bill_line.canonical_source_id IS DISTINCT FROM NEW.canonical_source_id
  OR NEW.canonical_source_type<>'PUR_ORDER_LINE_BASE' OR NEW.canonical_source_id IS DISTINCT FROM cost.po_line_id
  OR jxc_ap_cost_source_basis(parent.country_id,parent.book_id,parent.cost_id) IS DISTINCT FROM parent.source_basis THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_SOURCE_CHANGED';END IF;
 PERFORM jxc_assert_period_open(parent.country_id,parent.book_id,(parent.source_basis->>'confirmedBizDate')::date);
 selected_line:=NEW.id;
 SELECT coalesce(sum(base_qty),0) INTO used_qty FROM ap_cost_assignment_line WHERE country_id=NEW.country_id AND bill_line_id=NEW.bill_line_id AND id<>selected_line;
 IF used_qty+NEW.base_qty>claim.qty THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_CAPACITY_EXCEEDED';END IF;
 SELECT coalesce(sum(base_qty),0) INTO used_qty FROM ap_cost_assignment_line WHERE country_id=NEW.country_id AND assignment_id=NEW.assignment_id AND id<>selected_line;
 IF used_qty+NEW.base_qty>cost.qty THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_CAPACITY_EXCEEDED';END IF;
 IF NEW.economic_basis IS NOT NULL THEN
  expected_basis:=jsonb_build_object('billId',bill.id,'billLineId',bill_line.id,'bookId',bill.book_id,'partnerId',bill.partner_id,'currency',bill.currency,'baseCurrency',bill.base_currency,
   'billAmount',bill.amount,'billBaseAmount',bill.base_amount,'rate',bill.rate,'rateId',bill.rate_id,'rateDate',bill.rate_date,'lineAmount',bill_line.amount,
   'canonicalSourceType',NEW.canonical_source_type,'canonicalSourceId',NEW.canonical_source_id,'canonicalQty',claim.qty,'baseQty',NEW.base_qty,'principalAmount',NEW.principal_amount);
  IF NEW.economic_basis IS DISTINCT FROM expected_basis THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_SOURCE_CHANGED';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_cost_bill_dependency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN
  PERFORM jxc_ap_cost_basis_lock(OLD.country_id,OLD.book_id);
  IF EXISTS(SELECT 1 FROM ap_cost_assignment_line WHERE country_id=OLD.country_id AND bill_id=OLD.id) THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_IN_USE';END IF;
  RETURN OLD;
 END IF;
 IF NEW.status='VOIDED' AND NEW.status IS DISTINCT FROM OLD.status THEN
  PERFORM jxc_ap_cost_basis_lock(OLD.country_id,OLD.book_id);
  IF EXISTS(SELECT 1 FROM ap_cost_assignment_line WHERE country_id=OLD.country_id AND bill_id=OLD.id) THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_IN_USE';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_cost_claim_dependency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE selected_book bigint;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['version']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['version']) THEN RETURN NEW;END IF;
 END IF;
 SELECT book_id INTO selected_book FROM ap_bill WHERE country_id=OLD.country_id AND id=OLD.bill_id;
 PERFORM jxc_ap_cost_basis_lock(OLD.country_id,selected_book);
 IF EXISTS(SELECT 1 FROM ap_cost_assignment_line WHERE country_id=OLD.country_id AND bill_id=OLD.bill_id AND bill_line_id=OLD.bill_line_id) THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_IN_USE';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_cost_result_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE source_event sys_biz_event;source_cost cst_inbound_cost;
BEGIN
 SELECT * INTO source_event FROM sys_biz_event WHERE country_id=NEW.country_id AND id=NEW.event_id;
 IF source_event.event_type IS DISTINCT FROM 'CST_INBOUND_COST_CONFIRMED' OR source_event.source_type IS DISTINCT FROM 'CST_INBOUND_COST' THEN RETURN NEW;END IF;
 SELECT * INTO source_cost FROM cst_inbound_cost WHERE country_id=NEW.country_id AND id=source_event.source_id;
 IF source_cost.id IS NULL OR source_cost.book_id IS DISTINCT FROM NEW.book_id THEN RAISE EXCEPTION 'AP_COST_ASSIGNMENT_SOURCE_INVALID';END IF;
 IF source_cost.po_id IS NOT NULL THEN
  IF NOT jxc_ap_cost_current_intent(NEW.country_id,NEW.book_id,source_cost.id,NEW.event_id)
   OR NOT EXISTS(SELECT 1 FROM ap_cost_assignment a WHERE a.country_id=NEW.country_id AND a.book_id=NEW.book_id AND a.cost_id=source_cost.id AND a.status='FROZEN' AND a.frozen_event_id=NEW.event_id) THEN
   RAISE EXCEPTION 'AP_COST_ASSIGNMENT_REQUIRED';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_fx_dated_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE b bigint; d date;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'AP_FX_APPEND_ONLY'; END IF;
 SELECT s.book_id,s.biz_date INTO b,d FROM ap_settlement_line l JOIN ap_settlement s ON s.country_id=l.country_id AND s.id=l.settlement_id WHERE l.country_id=NEW.country_id AND l.id=NEW.settlement_line_id;
 IF b IS NULL THEN RAISE EXCEPTION 'SOURCE_MISSING' USING ERRCODE='23503';END IF;
 PERFORM jxc_assert_period_open(NEW.country_id,b,d);RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_purchase_claim_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE receipt_status text; order_status text; purchase_id bigint; purchase_line_id bigint;
BEGIN
 IF TG_OP='UPDATE' AND NOT NEW.effective THEN RETURN NEW;END IF;
 IF NEW.source_type IN ('PUR_ORDER_LINE','PUR_ORDER_LINE_BASE') THEN
  SELECT l.order_id INTO purchase_id FROM pur_order_line l WHERE l.country_id=NEW.country_id AND l.id=NEW.source_id FOR UPDATE;
  IF FOUND THEN SELECT status INTO order_status FROM pur_order WHERE country_id=NEW.country_id AND id=purchase_id;END IF;
 ELSIF NEW.source_type='PUR_RECEIPT_LINE' THEN
  SELECT r.status,l.order_line_id INTO receipt_status,purchase_line_id FROM pur_domestic_receipt_line l JOIN pur_domestic_receipt r ON r.country_id=l.country_id AND r.id=l.receipt_id WHERE l.country_id=NEW.country_id AND l.id=NEW.source_id FOR UPDATE OF l;
  IF receipt_status IS NOT NULL AND receipt_status<>'CONFIRMED' THEN RAISE EXCEPTION 'PUR_SOURCE_IN_USE: receipt is not confirmed' USING ERRCODE='23514';END IF;
  SELECT o.status INTO order_status FROM pur_order_line l JOIN pur_order o ON o.country_id=l.country_id AND o.id=l.order_id WHERE l.country_id=NEW.country_id AND l.id=purchase_line_id FOR UPDATE OF l;
 ELSE RETURN NEW;END IF;
 -- Missing rows are reported by the typed FK, preserving its exact provenance.
 IF order_status IS NOT NULL AND order_status NOT IN ('CONFIRMED','PARTIAL_DELIVERED','DELIVERED','CLOSED') THEN RAISE EXCEPTION 'PUR_SOURCE_IN_USE: purchase is not confirmed' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_settlement_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE s record; b record; h record; t text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'AP_SETTLEMENT_LINE_APPEND_ONLY';END IF;
 t:=CASE NEW.from_type WHEN 'PAYMENT' THEN 'ap_payment' WHEN 'PREPAYMENT' THEN 'ap_prepayment' WHEN 'CREDIT_NOTE' THEN 'ap_credit_note' END;
 IF t IS NULL THEN RAISE EXCEPTION 'AP_SOURCE_KIND_INVALID';END IF;
 EXECUTE format('SELECT book_id,entity_id,partner_type,partner_id,currency FROM %I WHERE country_id=$1 AND id=$2 FOR UPDATE',t) INTO s USING NEW.country_id,NEW.from_id;
 SELECT book_id,entity_id,partner_type,partner_id,currency INTO b FROM ap_bill WHERE country_id=NEW.country_id AND id=NEW.bill_id FOR UPDATE;
 SELECT book_id,entity_id,partner_type,partner_id INTO h FROM ap_settlement WHERE country_id=NEW.country_id AND id=NEW.settlement_id;
 IF s IS NULL OR b IS NULL OR h IS NULL OR (s.book_id,s.entity_id,s.partner_type,s.partner_id) IS DISTINCT FROM (b.book_id,b.entity_id,b.partner_type,b.partner_id) OR (h.book_id,h.entity_id,h.partner_type,h.partner_id) IS DISTINCT FROM (b.book_id,b.entity_id,b.partner_type,b.partner_id) OR s.currency<>NEW.from_currency OR b.currency<>NEW.bill_currency THEN RAISE EXCEPTION 'AP_SETTLEMENT_SOURCE_MISMATCH' USING ERRCODE='23503';END IF;
 IF NEW.from_type='PAYMENT' THEN NEW.payment_id:=NEW.from_id;ELSIF NEW.from_type='PREPAYMENT' THEN NEW.prepayment_id:=NEW.from_id;ELSE NEW.credit_note_id:=NEW.from_id;END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_ap_source_balance_consistency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE q numeric; a numeric; cap record;
BEGIN
 SELECT * INTO cap FROM ap_source_capacity WHERE country_id=NEW.country_id AND id=NEW.id;
 SELECT coalesce(sum(qty),0),coalesce(sum(amount),0) INTO q,a FROM ap_source_claim WHERE country_id=cap.country_id AND source_type=cap.source_type AND source_id=cap.source_id AND effective;
 IF cap.claimed_qty IS DISTINCT FROM q OR cap.claimed_amount IS DISTINCT FROM a THEN RAISE EXCEPTION 'AP_SOURCE_BALANCE_INCONSISTENT' USING ERRCODE='23514';END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_aprtn_account_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE account record;
BEGIN
 IF TG_TABLE_NAME='ap_prepayment' AND to_jsonb(NEW)->>'origin_kind'='OPENING' AND NEW.fund_account_id IS NULL THEN RETURN NEW;END IF;
 SELECT entity_id,book_id,currency INTO account FROM md_fund_account WHERE country_id=NEW.country_id AND id=NEW.fund_account_id;
 IF account IS NULL OR account.entity_id<>NEW.entity_id OR (account.book_id IS NOT NULL AND account.book_id<>NEW.book_id) OR account.currency<>NEW.currency THEN RAISE EXCEPTION 'PAYMENT_ACCOUNT_SOURCE_MISMATCH' USING ERRCODE='23503';END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_aprtn_child_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_id bigint; b bigint; d date; old_parent bigint; parent_status text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'BUSINESS_FACT_DELETE_FORBIDDEN'; END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME='rtn_sales_return_line' AND (to_jsonb(NEW)-ARRAY['received_qty','inspected_qty','good_qty','frozen_qty','freeze_type','reserved_qty','version']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['received_qty','inspected_qty','good_qty','frozen_qty','freeze_type','reserved_qty','version']) THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME='rtn_refund_source' AND (to_jsonb(NEW)-ARRAY['status','version']) IS NOT DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version']) THEN RETURN NEW; END IF;
 parent_id:=(to_jsonb(NEW)->>TG_ARGV[1])::bigint;
 EXECUTE format('SELECT book_id,%I FROM %I WHERE country_id=$1 AND id=$2',TG_ARGV[2],TG_ARGV[0]) INTO b,d USING NEW.country_id,parent_id;
 IF b IS NULL OR d IS NULL THEN RAISE EXCEPTION 'SOURCE_MISSING' USING ERRCODE='23503'; END IF;
 IF TG_TABLE_NAME IN ('ap_bill_line','rtn_sales_return_line','rtn_purchase_return_line') AND TG_OP='UPDATE' THEN
  EXECUTE format('SELECT status FROM %I WHERE country_id=$1 AND id=$2',TG_ARGV[0]) INTO parent_status USING NEW.country_id,parent_id;
  IF parent_status<>'DRAFT' THEN
  RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE' USING ERRCODE='23514';
  END IF;
 END IF;
 PERFORM jxc_assert_period_open(NEW.country_id,b,d);
 IF TG_OP='UPDATE' THEN old_parent:=(to_jsonb(OLD)->>TG_ARGV[1])::bigint;IF (OLD.country_id,old_parent) IS DISTINCT FROM (NEW.country_id,parent_id) THEN RAISE EXCEPTION 'SOURCE_IDENTITY_IMMUTABLE';END IF;END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_aprtn_dated_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d date; old_d date; mutable text; opening_batch bigint; expected_type text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'BUSINESS_FACT_DELETE_FORBIDDEN'; END IF;
 d:=(to_jsonb(NEW)->>TG_ARGV[0])::date;
 IF TG_OP='INSERT' AND TG_TABLE_NAME IN ('ap_bill','ap_prepayment') AND to_jsonb(NEW)->>'origin_kind'='OPENING' THEN
   IF NOT jxc_opening_import_allowed(NEW.country_id,d) THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SCOPE_REQUIRED' USING ERRCODE='23514';END IF;
   opening_batch:=current_setting('app.opening_import_batch')::bigint;
   expected_type:=CASE WHEN TG_TABLE_NAME='ap_bill' THEN 'OPENING_AP' ELSE 'OPENING_PREPAYMENT' END;
   IF NOT EXISTS(SELECT 1 FROM sys_import_batch b JOIN sys_import_row r ON r.country_id=b.country_id AND r.batch_id=b.id JOIN sys_import_source s ON s.country_id=r.country_id AND s.row_id=r.id AND s.import_type=b.import_type AND s.source_key=r.source_key WHERE b.country_id=NEW.country_id AND b.id=opening_batch AND b.import_type=expected_type AND b.status='VALIDATED' AND b.cutoff_date=d AND NEW.opening_source_ref='IMPORT:'||b.id||':'||r.row_no AND r.normalized->>'refNo'=NEW.opening_ref_no AND (r.normalized->>'bookId')::bigint=NEW.book_id AND (r.normalized->>'partnerId')::bigint=NEW.partner_id AND r.normalized->>'partnerType'=NEW.partner_type AND r.normalized->>'currency'=NEW.currency AND r.normalized->>'baseCurrency'=NEW.base_currency AND (r.normalized->>'rate')::numeric=NEW.rate AND NEW.rate_date=b.cutoff_date AND NEW.rate_id IS NULL AND NEW.valuation_status='READY' AND NEW.status='CONFIRMED' AND COALESCE((r.normalized->>'sourceDate')::date,b.cutoff_date)<=b.cutoff_date AND (r.normalized->>'amount')::numeric=NEW.amount AND (r.normalized->>'baseAmount')::numeric=NEW.base_amount) THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
   PERFORM id FROM sys_country WHERE id=NEW.country_id AND status<>'DISABLED' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'SYS_COUNTRY_DISABLED';END IF;
   PERFORM id FROM fin_book WHERE country_id=NEW.country_id AND id=NEW.book_id AND status='ACTIVE' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'FIN_BOOK_NOT_ACTIVE';END IF;
   IF NOT EXISTS(SELECT 1 FROM fin_period p WHERE p.country_id=NEW.country_id AND p.book_id=NEW.book_id AND p.start_date=d+1 AND p.status='OPEN') OR EXISTS(SELECT 1 FROM fin_period p WHERE p.country_id=NEW.country_id AND p.book_id=NEW.book_id AND p.start_date<d+1) THEN RAISE EXCEPTION 'FIN_OPENING_CUTOFF' USING ERRCODE='23514';END IF;
  RETURN NEW;
 END IF;

 mutable:=CASE TG_TABLE_NAME
  WHEN 'ap_bill' THEN 'paid_amount,status,version'
  WHEN 'ap_payment' THEN 'used_amount,status,version'
  WHEN 'ap_prepayment' THEN 'used_amount,status,version'
  WHEN 'ap_credit_note' THEN 'used_amount,status,version'
  WHEN 'ap_settlement' THEN 'status,version'
  WHEN 'ap_adjustment' THEN 'status,approval_instance_id,version'
  WHEN 'rtn_sales_return' THEN 'status,approval_instance_id,settled_flag,short_reason,version'
  WHEN 'rtn_refund' THEN 'status,approval_instance_id,paid_at,reference_no,paid_by,proof_attachment_id,version'
  WHEN 'rtn_purchase_return' THEN 'status,approval_instance_id,ap_credit_note_id,version'
  WHEN 'rtn_sales_settlement' THEN 'status,version'
  WHEN 'rtn_claim' THEN 'result,compensated_amount,ap_credit_note_id,version'
  WHEN 'rtn_sales_inspection' THEN 'inventory_batch_id,version'
  ELSE '' END;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME IN ('ap_bill','ap_adjustment','rtn_sales_return','rtn_refund','rtn_purchase_return') AND (to_jsonb(NEW)->>'status')='DRAFT' AND (to_jsonb(OLD)->>'status')<>'DRAFT' THEN RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE' USING ERRCODE='23514';END IF;
  IF TG_TABLE_NAME='ap_bill' AND (to_jsonb(OLD)->>'status')='VOIDED' AND (to_jsonb(NEW)->>'status')<>'VOIDED' THEN RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE' USING ERRCODE='23514';END IF;
  IF TG_TABLE_NAME IN ('ap_payment','ap_prepayment') AND (to_jsonb(NEW)->>'status')='PENDING_CONFIRM' AND (to_jsonb(OLD)->>'status')<>'PENDING_CONFIRM' THEN RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE' USING ERRCODE='23514';END IF;
  -- Confirmation and voiding create economic effects; only paid/used projections
  -- may follow a new settlement fact after the original period has closed.
  IF TG_TABLE_NAME='ap_bill' AND (to_jsonb(NEW)->>'status') IS DISTINCT FROM (to_jsonb(OLD)->>'status') AND ((to_jsonb(OLD)->>'status')='DRAFT' OR (to_jsonb(NEW)->>'status')='VOIDED') THEN
   PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.bill_date);
  ELSIF TG_TABLE_NAME IN ('ap_payment','ap_prepayment') AND (to_jsonb(NEW)->>'status') IS DISTINCT FROM (to_jsonb(OLD)->>'status') AND ((to_jsonb(OLD)->>'status')='PENDING_CONFIRM' OR (to_jsonb(NEW)->>'status')='VOIDED') THEN
   PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.pay_date);
  END IF;
  IF mutable<>'' AND (to_jsonb(NEW)-string_to_array(mutable,',')) IS NOT DISTINCT FROM (to_jsonb(OLD)-string_to_array(mutable,',')) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME IN ('ap_bill','ap_payment','ap_prepayment','ap_credit_note') THEN
   IF to_jsonb(OLD)->>'valuation_status'='PENDING_RATE' AND
      (to_jsonb(NEW)-ARRAY['base_currency','rate_id','rate','rate_date','base_amount','valuation_status','version']) IS NOT DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['base_currency','rate_id','rate','rate_date','base_amount','valuation_status','version']) THEN
    PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,(to_jsonb(OLD)->>TG_ARGV[0])::date);RETURN NEW;
   END IF;
   IF (TG_TABLE_NAME='ap_bill' AND OLD.status<>'DRAFT') OR
      (TG_TABLE_NAME IN ('ap_payment','ap_prepayment') AND OLD.status<>'PENDING_CONFIRM') OR
       TG_TABLE_NAME='ap_credit_note' THEN RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF TG_TABLE_NAME IN ('ap_settlement','rtn_sales_receipt','rtn_sales_settlement','rtn_sales_inspection','rtn_claim') OR (TG_TABLE_NAME IN ('ap_adjustment','rtn_sales_return','rtn_refund','rtn_purchase_return') AND (to_jsonb(OLD)->>'status')<>'DRAFT') THEN
   RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE' USING ERRCODE='23514';
  END IF;
 END IF;
 d:=(to_jsonb(NEW)->>TG_ARGV[0])::date;
 PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,d);
 IF TG_OP='UPDATE' THEN old_d:=(to_jsonb(OLD)->>TG_ARGV[0])::date;IF (OLD.country_id,OLD.book_id,old_d) IS DISTINCT FROM (NEW.country_id,NEW.book_id,d) THEN PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,old_d);END IF;END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_aprtn_partner_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE t text; p bigint;
BEGIN
 t:=coalesce(to_jsonb(NEW)->>'partner_type',to_jsonb(NEW)->>'against_type');p:=(to_jsonb(NEW)->>'partner_id')::bigint;
 IF t='SUPPLIER' THEN PERFORM id FROM md_supplier WHERE country_id=NEW.country_id AND id=p;
 ELSIF t='CARRIER' THEN PERFORM id FROM md_logistics_provider WHERE country_id=NEW.country_id AND id=p;
 ELSE RAISE EXCEPTION 'AP_PARTNER_TYPE_INVALID'; END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'AP_PARTNER_INVALID' USING ERRCODE='23503'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_assert_country_trade(selected_country bigint, document_date date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE country_status text;
BEGIN
 SELECT status INTO country_status FROM sys_country WHERE id=selected_country FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SYS_COUNTRY_REQUIRED';END IF;
 IF country_status='DISABLED' THEN RAISE EXCEPTION 'SYS_COUNTRY_DISABLED';END IF;
 IF country_status<>'ACTIVE' AND NOT jxc_opening_import_allowed(selected_country,document_date) THEN RAISE EXCEPTION 'SYS_COUNTRY_NOT_ACTIVE';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_assert_imported_opening_source_period(selected_country bigint, selected_book bigint, cutoff date, target_kind text, target_id bigint)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE doc jsonb;
BEGIN
 IF target_kind='PURCHASE_ORDER' THEN SELECT to_jsonb(p) INTO doc FROM pur_order p WHERE p.country_id=selected_country AND p.id=target_id;
 ELSIF target_kind='SHIPMENT' THEN SELECT to_jsonb(s) INTO doc FROM lgs_shipment s WHERE s.country_id=selected_country AND s.id=target_id;
 ELSE RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
 IF doc IS NULL OR (doc->>'book_id')::bigint IS DISTINCT FROM selected_book OR (doc->>'cutoff_date')::date IS DISTINCT FROM cutoff THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
 PERFORM jxc_supply_opening_basis(doc,target_kind,true);
 PERFORM jxc_assert_country_trade(selected_country,NULL);
 PERFORM jxc_assert_opening_cutoff_period(selected_country,selected_book,cutoff);
END $function$

CREATE OR REPLACE FUNCTION public.jxc_assert_opening_cutoff_period(selected_country bigint, selected_book bigint, cutoff date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE first_start date;
BEGIN
 IF EXISTS(SELECT 1 FROM fin_period WHERE country_id=selected_country AND book_id=selected_book AND cutoff BETWEEN start_date AND end_date) THEN
  PERFORM id FROM fin_period WHERE country_id=selected_country AND book_id=selected_book AND cutoff BETWEEN start_date AND end_date FOR SHARE;
  PERFORM jxc_assert_period_state(selected_country,selected_book,cutoff);RETURN;
 END IF;
 SELECT min(start_date) INTO first_start FROM fin_period WHERE country_id=selected_country AND book_id=selected_book;
 IF cutoff IS NULL OR first_start IS DISTINCT FROM cutoff+1 THEN RAISE EXCEPTION 'FIN_OPENING_CUTOFF' USING ERRCODE='23514';END IF;
 PERFORM id FROM fin_period WHERE country_id=selected_country AND book_id=selected_book AND start_date=first_start FOR SHARE;
 PERFORM jxc_assert_period_state(selected_country,selected_book,first_start);
END $function$

CREATE OR REPLACE FUNCTION public.jxc_assert_period_state(p_country_id bigint, p_book_id bigint, p_biz_date date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE book_status text;period_status text;
BEGIN
 SELECT status INTO book_status FROM fin_book WHERE country_id=p_country_id AND id=p_book_id FOR SHARE;
 IF NOT FOUND OR book_status<>'ACTIVE' THEN RAISE EXCEPTION 'FIN_BOOK_NOT_ACTIVE' USING ERRCODE='P0001';END IF;
 SELECT status INTO period_status FROM fin_period WHERE country_id=p_country_id AND book_id=p_book_id AND p_biz_date BETWEEN start_date AND end_date;
 IF NOT FOUND THEN RAISE EXCEPTION 'FIN_PERIOD_NOT_FOUND' USING ERRCODE='P0001';END IF;
 IF period_status<>'OPEN' THEN RAISE EXCEPTION 'FIN_PERIOD_CLOSED' USING ERRCODE='P0001';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_assert_subledger_opening_fact(fact_table text, fact jsonb)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE selected_country bigint;selected_book bigint;document_day date;selected_row_id bigint;import_batch_id bigint;requested_user bigint;expected_type text;reviewed jsonb;base text;quantity numeric;unit_price numeric;valued_unit numeric;
BEGIN
 selected_country:=(fact->>'country_id')::bigint;selected_book:=(fact->>'book_id')::bigint;document_day:=(fact->>'biz_date')::date;
 expected_type:=CASE fact_table WHEN 'inv_stock_txn' THEN 'OPENING_STOCK' WHEN 'cst_inbound_cost' THEN 'OPENING_STOCK' WHEN 'cst_valuation_movement' THEN 'OPENING_STOCK' WHEN 'ar_receivable' THEN 'OPENING_AR' WHEN 'ar_credit_note' THEN 'OPENING_ADVANCE' END;
 IF expected_type IS NULL OR fact->>'source_type' IS DISTINCT FROM expected_type OR NOT jxc_opening_import_allowed(selected_country,document_day) THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SCOPE_REQUIRED' USING ERRCODE='23514';END IF;
 selected_row_id:=(CASE WHEN expected_type='OPENING_STOCK' THEN fact->>'source_line_id' ELSE fact->>'import_row_id' END)::bigint;
 SELECT r.normalized,b.id,b.requested_by INTO reviewed,import_batch_id,requested_user
 FROM sys_import_batch b JOIN sys_import_row r ON r.country_id=b.country_id AND r.batch_id=b.id
 JOIN sys_import_source s ON s.country_id=r.country_id AND s.row_id=r.id AND s.import_type=b.import_type AND s.source_key=r.source_key
 WHERE b.country_id=selected_country AND b.id=current_setting('app.opening_import_batch')::bigint AND b.import_type=expected_type AND b.status='VALIDATED'
 AND b.cutoff_date=document_day AND r.id=selected_row_id AND r.errors='[]'::jsonb AND r.target_id IS NULL;
 IF NOT FOUND OR (reviewed->>'bookId')::bigint IS DISTINCT FROM selected_book OR reviewed->>'sourceDate' IS NULL OR (reviewed->>'sourceDate')::date>document_day THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
 PERFORM jxc_assert_country_trade(selected_country,document_day);
 SELECT base_currency INTO base FROM fin_book WHERE country_id=selected_country AND id=selected_book;
 IF expected_type='OPENING_STOCK' THEN
  quantity:=(reviewed->>'qty')::numeric;unit_price:=(reviewed->>'unitCost')::numeric;valued_unit:=round(round(quantity*unit_price,4)/quantity,4);
  IF ROW((fact->>'warehouse_id')::bigint,(fact->>'product_id')::bigint) IS DISTINCT FROM ROW((reviewed->>'warehouseId')::bigint,(reviewed->>'productId')::bigint)
   OR NOT EXISTS(SELECT 1 FROM inv_batch b WHERE b.country_id=selected_country AND b.id=(fact->>'batch_id')::bigint AND b.book_id=selected_book AND b.product_id=(reviewed->>'productId')::bigint AND b.source_type='OPENING_STOCK' AND b.source_id=import_batch_id AND b.source_line_id=selected_row_id AND b.first_inbound_date=document_day AND b.cutoff_date=document_day AND b.opening_warehouse_id=(reviewed->>'warehouseId')::bigint AND b.opening_batch_no=reviewed->>'batchNo') THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
  IF fact_table='inv_stock_txn' THEN
   IF (fact->>'source_id')::bigint IS DISTINCT FROM import_batch_id OR fact->>'source_no' IS DISTINCT FROM reviewed->>'refNo' OR fact->>'txn_type' IS DISTINCT FROM 'OPENING_IN'
    OR (fact->>'on_hand_change')::numeric IS DISTINCT FROM quantity OR (fact->>'frozen_change')::numeric IS DISTINCT FROM 0::numeric OR (fact->>'seq')::integer IS DISTINCT FROM 1 OR (fact->>'operator_id')::bigint IS DISTINCT FROM requested_user OR (fact->>'unit_cost')::numeric IS DISTINCT FROM valued_unit THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
  ELSIF fact_table='cst_inbound_cost' THEN
   IF (fact->>'qty')::numeric IS DISTINCT FROM quantity OR (fact->>'src_unit_price')::numeric IS DISTINCT FROM unit_price OR (fact->>'unit_cost')::numeric IS DISTINCT FROM valued_unit
    OR (fact->>'src_amount')::numeric IS DISTINCT FROM round(quantity*unit_price,4) OR (fact->>'base_purchase_amount')::numeric IS DISTINCT FROM round(quantity*unit_price,4)
    OR fact->>'src_currency' IS DISTINCT FROM base OR fact->>'base_currency' IS DISTINCT FROM base OR (fact->>'rate')::numeric IS DISTINCT FROM 1::numeric OR (fact->>'rate_date')::date IS DISTINCT FROM document_day OR fact->>'rate_id' IS NOT NULL
    OR fact->>'status' IS DISTINCT FROM 'ESTIMATED' OR fact->>'po_id' IS NOT NULL OR fact->>'po_line_id' IS NOT NULL OR fact->>'original_outbound_line_id' IS NOT NULL OR fact->>'source_cost_id' IS NOT NULL THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
  ELSE
   IF fact->>'action' IS DISTINCT FROM 'INBOUND' OR (fact->>'seq')::integer IS DISTINCT FROM 1 OR (fact->>'qty_change')::numeric IS DISTINCT FROM quantity
    OR (fact->>'amount_change')::numeric IS DISTINCT FROM round(quantity*unit_price,4) OR fact->>'cogs_id' IS NOT NULL OR fact->>'transfer_cost_id' IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM cst_inbound_cost c WHERE c.country_id=selected_country AND c.book_id=selected_book AND c.batch_id=(fact->>'batch_id')::bigint AND c.source_type='OPENING_STOCK' AND c.source_line_id=selected_row_id AND c.biz_date=document_day AND c.qty=quantity AND c.base_purchase_amount=(fact->>'amount_change')::numeric)
   THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
  END IF;
 ELSE
  IF (fact->>'source_id')::bigint IS DISTINCT FROM selected_row_id OR fact->>'opening_ref' IS DISTINCT FROM reviewed->>'refNo' OR (fact->>'cutoff_date')::date IS DISTINCT FROM document_day
   OR (fact->>'customer_id')::bigint IS DISTINCT FROM (reviewed->>'customerId')::bigint OR fact->>'currency' IS DISTINCT FROM reviewed->>'currency' OR fact->>'currency' IS DISTINCT FROM base OR (fact->>'amount')::numeric IS DISTINCT FROM (reviewed->>'amount')::numeric OR fact->>'order_id' IS NOT NULL THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
  IF expected_type='OPENING_AR' THEN
   IF (fact->>'open_amount')::numeric IS DISTINCT FROM (reviewed->>'amount')::numeric OR (fact->>'written_off_amount')::numeric IS DISTINCT FROM 0::numeric OR (fact->>'due_date')::date IS DISTINCT FROM (reviewed->>'dueDate')::date THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
  ELSIF fact->>'purpose' IS DISTINCT FROM 'OFFSET' OR (fact->>'refundable_flag')::boolean IS DISTINCT FROM false OR (fact->>'used_amount')::numeric IS DISTINCT FROM 0::numeric OR (fact->>'reserved_amount')::numeric IS DISTINCT FROM 0::numeric THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';
  END IF;
 END IF;
 PERFORM jxc_assert_opening_cutoff_period(selected_country,selected_book,document_day);
END $function$

CREATE OR REPLACE FUNCTION public.jxc_assert_writes_open()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE current_mode text;
BEGIN
 -- FOR SHARE is deliberate: a stale REPEATABLE READ writer fails serialization after
 -- a mode change, rather than observing the OPEN value in its old MVCC snapshot.
 SELECT mode INTO current_mode FROM public.sys_write_control WHERE singleton FOR SHARE;
 IF NOT FOUND OR current_mode<>'OPEN' THEN
  RAISE EXCEPTION 'SYS_WRITES_FROZEN' USING ERRCODE='P0001';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_attachment_identity_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'JXC_IMMUTABLE_ATTACHMENT' USING ERRCODE='P0001'; END IF;
  IF TG_TABLE_NAME='sys_attachment' THEN
    IF (to_jsonb(NEW)-ARRAY['status','object_status','version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','object_status','version']) THEN
      RAISE EXCEPTION 'JXC_IMMUTABLE_ATTACHMENT' USING ERRCODE='P0001';
    END IF;
  ELSE
    IF (to_jsonb(NEW)-ARRAY['unlinked_at','version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['unlinked_at','version'])
       OR (OLD.unlinked_at IS NOT NULL AND NEW.unlinked_at IS DISTINCT FROM OLD.unlinked_at) THEN
      RAISE EXCEPTION 'JXC_IMMUTABLE_ATTACHMENT_LINK' USING ERRCODE='P0001';
    END IF;
  END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.jxc_close_waiver_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p fin_period;
BEGIN
 SELECT * INTO p FROM fin_period WHERE country_id=NEW.country_id AND book_id=NEW.book_id AND id=NEW.period_id;
 IF NOT FOUND OR p.status NOT IN ('OPEN','PENDING_CLOSE') OR NEW.close_generation<>p.close_generation+1 THEN RAISE EXCEPTION 'FIN_WAIVER_STALE';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_cost_part_ownership_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE parent record;batch record;source record;BEGIN
 SELECT * INTO batch FROM inv_batch WHERE country_id=NEW.country_id AND id=NEW.batch_id;
 IF TG_TABLE_NAME='cst_cogs_part' THEN
  SELECT * INTO parent FROM cst_cogs WHERE country_id=NEW.country_id AND id=NEW.cogs_id;
  IF NEW.cost_id IS NOT NULL THEN SELECT * INTO source FROM cst_inbound_cost WHERE country_id=NEW.country_id AND id=NEW.cost_id;
   IF source.book_id<>parent.book_id OR source.batch_id<>NEW.batch_id THEN RAISE EXCEPTION 'CST_SOURCE_BOOK_MISMATCH';END IF;
  END IF;
 ELSE SELECT * INTO parent FROM cst_transfer_cost WHERE country_id=NEW.country_id AND id=NEW.transfer_cost_id;
 END IF;
 IF batch.book_id<>parent.book_id OR batch.product_id<>parent.product_id THEN RAISE EXCEPTION 'CST_SOURCE_BOOK_MISMATCH';END IF;RETURN NEW;END $function$

CREATE OR REPLACE FUNCTION public.jxc_cost_pool_conservation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c bigint;w bigint;p bigint;b bigint;pool record;physical numeric;
BEGIN
 c:=COALESCE(NEW.country_id,OLD.country_id);w:=COALESCE(NEW.warehouse_id,OLD.warehouse_id);p:=COALESCE(NEW.product_id,OLD.product_id);
 FOR pool IN SELECT book_id,qty FROM cst_valuation_pool WHERE country_id=c AND warehouse_id=w AND product_id=p LOOP
  SELECT coalesce(sum(bb.on_hand_qty),0) INTO physical FROM inv_batch_balance bb JOIN inv_batch ib ON ib.country_id=bb.country_id AND ib.id=bb.batch_id WHERE bb.country_id=c AND bb.warehouse_id=w AND bb.product_id=p AND ib.book_id=pool.book_id;
  IF pool.qty<>physical THEN RAISE EXCEPTION 'CST_POOL_QUANTITY_MISMATCH'; END IF;
 END LOOP;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_cost_projection_binding()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE movement record;current_value record;BEGIN
 IF TG_OP='UPDATE' AND NEW.amount IS NOT DISTINCT FROM OLD.amount THEN RETURN NULL;END IF;
 SELECT * INTO movement FROM cst_valuation_movement WHERE country_id=NEW.country_id AND book_id=NEW.book_id AND warehouse_id=NEW.warehouse_id AND product_id=NEW.product_id AND command_txid=txid_current() ORDER BY id DESC LIMIT 1;
 IF movement.id IS NULL THEN RAISE EXCEPTION 'CST_PROJECTION_SOURCE_REQUIRED';END IF;
 IF TG_TABLE_NAME='cst_valuation_pool' THEN
  SELECT qty,amount INTO current_value FROM cst_valuation_pool WHERE country_id=NEW.country_id AND book_id=NEW.book_id AND warehouse_id=NEW.warehouse_id AND product_id=NEW.product_id;
  IF current_value.qty<>movement.after_qty OR current_value.amount IS DISTINCT FROM movement.after_amount THEN RAISE EXCEPTION 'CST_PROJECTION_MOVEMENT_MISMATCH';END IF;
 END IF;RETURN NULL;END $function$

CREATE OR REPLACE FUNCTION public.jxc_country_mutation_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE value jsonb;selected_country bigint;country_status text;day date;
BEGIN
 value:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 selected_country:=(value->>'country_id')::bigint;
 IF selected_country=0 OR TG_TABLE_NAME IN('sys_authz_epoch','sys_audit_log','sys_idempotency','sys_export_job','sys_job_result','sys_job_execution_intent','sys_notification','sys_worker_runtime') THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END IF;
 -- Finite historical exports keep their existing owner/session/source guards and never mutate facts.
 IF TG_TABLE_NAME='sys_biz_event' AND value->>'source_type'='SYS_REPORT_EXPORT' AND value->>'event_type'='SYS_REPORT_EXPORT_REQUESTED' AND (value->>'event_seq')::integer=1 AND EXISTS(SELECT 1 FROM sys_export_job j WHERE j.country_id=selected_country AND j.book_id=(value->>'book_id')::bigint AND j.id=(value->>'source_id')::bigint) THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END IF;
 IF TG_TABLE_NAME='sys_biz_event_consume' AND value->>'consumer'='SYS_EXPORT' AND EXISTS(SELECT 1 FROM sys_biz_event e WHERE e.country_id=selected_country AND e.id=(value->>'event_id')::bigint AND e.source_type='SYS_REPORT_EXPORT' AND e.event_type='SYS_REPORT_EXPORT_REQUESTED') THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;END IF;
 SELECT status INTO country_status FROM sys_country WHERE id=selected_country FOR SHARE;
 IF country_status='DISABLED' THEN RAISE EXCEPTION 'SYS_COUNTRY_DISABLED';END IF;
 IF TG_ARGV[0]='TRADE' AND country_status<>'ACTIVE' THEN
  day:=coalesce((value->>'biz_date')::date,(value->>'order_date')::date,(value->>'bill_date')::date,(value->>'pay_date')::date,(value->>'receipt_date')::date,(value->>'voucher_date')::date,(value->>'opening_date')::date);
  IF day IS NULL THEN
   -- Child facts carry the same server-only import transaction and inherit its validated cutoff.
   IF coalesce(current_setting('app.opening_import_batch',true),'') ~ '^[1-9][0-9]{0,15}$' THEN SELECT cutoff_date INTO day FROM sys_import_batch WHERE country_id=selected_country AND id=current_setting('app.opening_import_batch',true)::bigint AND status='VALIDATED';END IF;
  END IF;
  IF NOT jxc_opening_import_allowed(selected_country,day) THEN RAISE EXCEPTION 'SYS_COUNTRY_NOT_ACTIVE';END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_country_template_freeze()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent_status text;
BEGIN
 IF TG_TABLE_NAME='sys_country_template_item' THEN
  IF TG_OP<>'INSERT' THEN
   SELECT status INTO parent_status FROM sys_country_template WHERE country_id=OLD.country_id AND id=OLD.template_id FOR SHARE;
   IF parent_status IS DISTINCT FROM 'DRAFT' THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  END IF;
  IF TG_OP<>'DELETE' THEN
   SELECT status INTO parent_status FROM sys_country_template WHERE country_id=NEW.country_id AND id=NEW.template_id FOR SHARE;
   IF parent_status IS DISTINCT FROM 'DRAFT' THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='sys_country_template' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'DRAFT' OR NEW.published_by IS NOT NULL OR NEW.published_at IS NOT NULL THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF TG_OP='DELETE' THEN
   IF OLD.status<>'DRAFT' THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF OLD.status<>'DRAFT' THEN
   IF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') OR NOT(NEW.status=OLD.status OR OLD.status='PUBLISHED' AND NEW.status='RETIRED') THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSE
   IF ROW(NEW.id,NEW.country_id,NEW.version_no,NEW.created_by,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.version_no,OLD.created_by,OLD.created_at)
    OR NEW.status NOT IN('DRAFT','PUBLISHED')
    OR NEW.status='PUBLISHED' AND (NEW.published_by IS NULL OR NEW.published_at IS NULL)
    OR NEW.status='DRAFT' AND (NEW.published_by IS NOT NULL OR NEW.published_at IS NOT NULL) THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='sys_country_clone_job' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.status<>'DRAFT' OR NEW.applied_at IS NOT NULL THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF TG_OP='DELETE' THEN
   IF OLD.status<>'DRAFT' THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF OLD.status<>'DRAFT' THEN
   IF (to_jsonb(NEW)-'status') IS DISTINCT FROM (to_jsonb(OLD)-'status') OR NOT(NEW.status=OLD.status OR OLD.status='APPLIED' AND NEW.status='DONE') THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF (to_jsonb(NEW)-ARRAY['selected_item_ids','copy_result','status','applied_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['selected_item_ids','copy_result','status','applied_at'])
   OR NEW.status NOT IN('DRAFT','APPLIED','CANCELLED') OR NEW.status='APPLIED' AND NEW.applied_at IS NULL OR NEW.status<>'APPLIED' AND NEW.applied_at IS NOT NULL THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';
  END IF;
 ELSIF TG_TABLE_NAME='sys_country_config_review' THEN
  IF TG_OP='INSERT' THEN
   IF NEW.review_status<>'NEED_REVIEW' OR NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL OR NEW.comment<>'' THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF TG_OP='DELETE' THEN
   IF OLD.review_status='REVIEWED' THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF OLD.review_status='REVIEWED' THEN
   IF to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';END IF;
  ELSIF (to_jsonb(NEW)-ARRAY['review_status','reviewed_by','reviewed_at','comment']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['review_status','reviewed_by','reviewed_at','comment'])
   OR NEW.review_status<>'REVIEWED' OR NEW.reviewed_by IS NULL OR NEW.reviewed_at IS NULL OR btrim(NEW.comment)='' THEN RAISE EXCEPTION 'SYS_TEMPLATE_IMMUTABLE' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_fin_assert_balance(p_id bigint)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE b fin_account_balance;p fin_period;op numeric;pd numeric;pc numeric;original numeric;opening_original numeric;ob numeric;
BEGIN
 SELECT * INTO b FROM fin_account_balance WHERE id=p_id;IF NOT FOUND THEN RETURN;END IF;
 SELECT * INTO p FROM fin_period WHERE country_id=b.country_id AND book_id=b.book_id AND id=b.period_id;
 SELECT COALESCE(sum(l.debit-l.credit) FILTER(WHERE v.voucher_date<p.start_date),0),COALESCE(sum(l.debit) FILTER(WHERE v.period_id=p.id),0),COALESCE(sum(l.credit) FILTER(WHERE v.period_id=p.id),0),COALESCE(sum(CASE WHEN l.debit<>0 THEN l.orig_amount ELSE -l.orig_amount END),0) INTO op,pd,pc,original
 FROM fin_voucher_line l JOIN fin_voucher v ON v.country_id=l.country_id AND v.id=l.voucher_id WHERE l.country_id=b.country_id AND l.book_id=b.book_id AND l.account_id=b.account_id AND l.aux_key=b.aux_key AND l.currency=b.currency AND v.status IN ('POSTED','REVERSED') AND v.voucher_date<=p.end_date;
 SELECT COALESCE(sum(CASE WHEN direction='DEBIT' THEN base_amount ELSE -base_amount END),0),COALESCE(sum(CASE WHEN direction='DEBIT' THEN orig_amount ELSE -orig_amount END),0) INTO ob,opening_original FROM fin_opening_balance WHERE country_id=b.country_id AND book_id=b.book_id AND account_id=b.account_id AND aux_key=b.aux_key AND currency=b.currency AND status='CONFIRMED' AND cutoff_date<p.start_date;
 IF b.opening_debit-b.opening_credit<>op+ob OR b.period_debit<>pd OR b.period_credit<>pc OR b.orig_closing<>original+opening_original THEN RAISE EXCEPTION 'FIN_BALANCE_FACT_MISMATCH';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_fin_balanced()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE h fin_voucher;d numeric;c numeric;n int;BEGIN
 SELECT * INTO h FROM fin_voucher WHERE country_id=COALESCE(NEW.country_id,OLD.country_id) AND id=COALESCE((to_jsonb(NEW)->>CASE WHEN TG_TABLE_NAME='fin_voucher' THEN 'id' ELSE 'voucher_id' END)::bigint,(to_jsonb(OLD)->>CASE WHEN TG_TABLE_NAME='fin_voucher' THEN 'id' ELSE 'voucher_id' END)::bigint);
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT count(*),COALESCE(sum(debit),0),COALESCE(sum(credit),0) INTO n,d,c FROM fin_voucher_line WHERE country_id=h.country_id AND voucher_id=h.id;
 IF n<2 OR d<>c OR d<>h.total_debit OR c<>h.total_credit THEN RAISE EXCEPTION 'FIN_UNBALANCED';END IF;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_fin_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE h fin_voucher;BEGIN
 SELECT * INTO h FROM fin_voucher WHERE country_id=COALESCE(NEW.country_id,OLD.country_id) AND id=COALESCE(NEW.voucher_id,OLD.voucher_id) FOR UPDATE;
 IF h.status IN ('POSTED','REVERSED') OR TG_OP='UPDATE' OR (TG_OP='DELETE' AND h.status<>'DRAFT') THEN RAISE EXCEPTION 'FIN_POSTED_LOCKED';END IF;
 PERFORM jxc_assert_period_open(h.country_id,h.book_id,h.voucher_date);RETURN COALESCE(NEW,OLD);
END $function$

CREATE OR REPLACE FUNCTION public.jxc_fin_opening_projection_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE o fin_opening_balance;cutoffs int;cutoff date;net numeric;r record;balance_id bigint;
BEGIN
 SELECT * INTO o FROM fin_opening_balance WHERE country_id=NEW.country_id AND id=NEW.id;
 IF NOT FOUND OR o.status<>'CONFIRMED' THEN RETURN NULL;END IF;
 IF EXISTS(SELECT 1 FROM fin_opening_balance WHERE country_id=o.country_id AND book_id=o.book_id AND status='CONFIRMED' AND (confirmed_by IS NULL OR confirmed_at IS NULL)) THEN RAISE EXCEPTION 'FIN_OPENING_CONFIRMATION_REQUIRED';END IF;
 SELECT count(DISTINCT cutoff_date),min(cutoff_date),COALESCE(sum(CASE WHEN direction='DEBIT' THEN base_amount ELSE -base_amount END),0) INTO cutoffs,cutoff,net FROM fin_opening_balance WHERE country_id=o.country_id AND book_id=o.book_id AND status='CONFIRMED';
 IF net<>0 THEN RAISE EXCEPTION 'FIN_UNBALANCED';END IF;
 IF cutoffs<>1 THEN RAISE EXCEPTION 'FIN_OPENING_CUTOFF_MISMATCH';END IF;
 IF NOT EXISTS(SELECT 1 FROM fin_period WHERE country_id=o.country_id AND book_id=o.book_id AND start_date=cutoff+1 AND status='OPEN') THEN RAISE EXCEPTION 'FIN_OPENING_PERIOD';END IF;
 PERFORM jxc_assert_opening_projection_period(o.country_id,o.book_id,cutoff);
 IF EXISTS(SELECT 1 FROM fin_voucher WHERE country_id=o.country_id AND book_id=o.book_id AND status IN ('POSTED','REVERSED') AND voucher_date<=cutoff) THEN RAISE EXCEPTION 'FIN_OPENING_CUTOFF';END IF;
 IF EXISTS(SELECT 1 FROM fin_voucher WHERE country_id=o.country_id AND book_id=o.book_id AND status IN ('POSTED','REVERSED')) THEN RAISE EXCEPTION 'FIN_OPENING_LOCKED';END IF;
 FOR r IN SELECT DISTINCT p.id period_id,b.account_id,b.aux_key,b.currency FROM fin_opening_balance b JOIN fin_period p ON p.country_id=b.country_id AND p.book_id=b.book_id AND p.start_date>cutoff WHERE b.country_id=o.country_id AND b.book_id=o.book_id AND b.status='CONFIRMED' LOOP
  SELECT id INTO balance_id FROM fin_account_balance WHERE country_id=o.country_id AND book_id=o.book_id AND period_id=r.period_id AND account_id=r.account_id AND aux_key=r.aux_key AND currency=r.currency;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIN_BALANCE_PROJECTION_MISSING';END IF;PERFORM jxc_fin_assert_balance(balance_id);
 END LOOP;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_fin_posting_projection_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE v fin_voucher;r record;balance_id bigint;BEGIN
 SELECT * INTO v FROM fin_voucher WHERE country_id=NEW.country_id AND id=NEW.id;IF NOT FOUND OR v.status NOT IN ('POSTED','REVERSED') THEN RETURN NULL;END IF;
 FOR r IN SELECT DISTINCT p.id period_id,l.account_id,l.aux_key,l.currency FROM fin_voucher_line l JOIN fin_period p ON p.country_id=l.country_id AND p.book_id=l.book_id AND (p.id=v.period_id OR p.start_date>v.voucher_date AND p.status IN ('OPEN','PENDING_CLOSE')) WHERE l.country_id=v.country_id AND l.voucher_id=v.id LOOP
  SELECT id INTO balance_id FROM fin_account_balance WHERE country_id=v.country_id AND book_id=v.book_id AND period_id=r.period_id AND account_id=r.account_id AND aux_key=r.aux_key AND currency=r.currency;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIN_BALANCE_PROJECTION_MISSING';END IF;PERFORM jxc_fin_assert_balance(balance_id);
 END LOOP;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_fin_voucher_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' THEN IF OLD.status<>'DRAFT' OR OLD.source_kind<>'MANUAL' THEN RAISE EXCEPTION 'FIN_POSTED_LOCKED';END IF;PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.voucher_date);RETURN OLD;END IF;
 IF TG_OP='UPDATE' AND OLD.status IN ('POSTED','REVERSED') THEN
  IF (to_jsonb(NEW)-ARRAY['status','reversed_by_id','version','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','reversed_by_id','version','updated_at']) OR NOT(OLD.status='POSTED' AND NEW.status='REVERSED' AND NEW.reversed_by_id IS NOT NULL AND EXISTS(SELECT 1 FROM fin_voucher r WHERE r.country_id=OLD.country_id AND r.book_id=OLD.book_id AND r.id=NEW.reversed_by_id AND r.reversal_of_id=OLD.id AND r.status='POSTED')) THEN RAISE EXCEPTION 'FIN_POSTED_LOCKED';END IF;RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' THEN PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.voucher_date);END IF;
 PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,NEW.voucher_date);
 IF EXISTS(SELECT 1 FROM fin_opening_balance o WHERE o.country_id=NEW.country_id AND o.book_id=NEW.book_id AND o.status='CONFIRMED' AND o.cutoff_date>=NEW.voucher_date) THEN RAISE EXCEPTION 'FIN_OPENING_CUTOFF';END IF;
 IF NOT EXISTS(SELECT 1 FROM fin_period p WHERE p.country_id=NEW.country_id AND p.book_id=NEW.book_id AND p.id=NEW.period_id AND NEW.voucher_date BETWEEN p.start_date AND p.end_date) THEN RAISE EXCEPTION 'FIN_PERIOD_MISMATCH';END IF;
 IF TG_OP='UPDATE' AND OLD.status<>'DRAFT' AND (to_jsonb(NEW)-ARRAY['status','audited_by','audited_at','posted_by','posted_at','unaudit_reason','version','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','audited_by','audited_at','posted_by','posted_at','unaudit_reason','version','updated_at']) THEN RAISE EXCEPTION 'FIN_POSTED_LOCKED';END IF;
 IF NEW.status IN ('AUDITED','POSTED','REVERSED') AND (NEW.audited_by IS NULL OR NEW.audited_by=NEW.prepared_by) THEN RAISE EXCEPTION 'FIN_AUDITOR_CONFLICT';END IF;
 IF NEW.status='POSTED' AND (NEW.posted_by IS NULL OR NEW.posted_at IS NULL OR TG_OP='INSERT' OR OLD.status<>'AUDITED') THEN RAISE EXCEPTION 'FIN_STATUS_CONFLICT';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_finalize_period(p_country bigint, p_book bigint, p_period bigint, p_user bigint, p_balance jsonb, p_report jsonb, p_reconcile jsonb, p_sources jsonb, p_fingerprint text, p_checks jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p public.fin_period;n integer;bad_count integer;expected_count integer;item jsonb;next_start date;next_end date;next_id bigint;
BEGIN
 IF p_country IS DISTINCT FROM public.jxc_current_country_id() THEN RAISE EXCEPTION 'SYS_COUNTRY_REQUIRED';END IF;
 PERFORM 1 FROM public.fin_book WHERE country_id=p_country AND id=p_book AND status='ACTIVE' FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'FIN_BOOK_NOT_ACTIVE';END IF;
 SELECT * INTO p FROM public.fin_period WHERE country_id=p_country AND book_id=p_book AND id=p_period FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'FIN_PERIOD_NOT_FOUND';END IF;
 IF p.status='CLOSED' THEN RETURN p.close_generation;END IF;
 IF p.status NOT IN ('OPEN','PENDING_CLOSE') THEN RAISE EXCEPTION 'FIN_PERIOD_NOT_OPEN';END IF;n:=p.close_generation+1;
 IF EXISTS(SELECT 1 FROM public.sys_biz_event e LEFT JOIN public.fin_event_result r ON r.country_id=e.country_id AND r.event_id=e.id LEFT JOIN public.sys_biz_event_consume c ON c.country_id=e.country_id AND c.event_id=e.id AND c.consumer='FIN_VOUCHER' WHERE e.country_id=p_country AND e.book_id=p_book AND e.biz_date BETWEEN p.start_date AND p.end_date AND NOT(e.source_type='SYS_REPORT_EXPORT' AND e.event_type='SYS_REPORT_EXPORT_REQUESTED') AND (r.id IS NULL OR e.status='FAILED' OR c.status='FAILED')) THEN RAISE EXCEPTION 'FIN_CLOSE_EVENTS_OPEN';END IF;
 IF EXISTS(SELECT 1 FROM public.fin_voucher WHERE country_id=p_country AND book_id=p_book AND period_id=p_period AND (status NOT IN ('POSTED','REVERSED') OR total_debit<>total_credit)) THEN RAISE EXCEPTION 'FIN_CLOSE_VOUCHER_BLOCKED';END IF;
 IF EXISTS(SELECT 1 FROM public.fin_voucher v LEFT JOIN public.fin_voucher_line l ON l.country_id=v.country_id AND l.voucher_id=v.id WHERE v.country_id=p_country AND v.book_id=p_book AND v.period_id=p_period GROUP BY v.id HAVING count(l.id)<2 OR sum(l.debit)<>sum(l.credit) OR sum(l.debit)<>v.total_debit OR sum(l.credit)<>v.total_credit) THEN RAISE EXCEPTION 'FIN_CLOSE_UNBALANCED';END IF;
 IF EXISTS(SELECT 1 FROM public.fin_voucher_line l JOIN public.fin_voucher v ON v.country_id=l.country_id AND v.id=l.voucher_id JOIN public.fin_account a ON a.country_id=l.country_id AND a.id=l.account_id WHERE v.country_id=p_country AND v.book_id=p_book AND v.period_id=p_period AND (a.is_cash OR a.is_bank) AND l.cashflow_item_id IS NULL) THEN RAISE EXCEPTION 'FIN_CASHFLOW_REQUIRED';END IF;
 IF jsonb_typeof(p_balance->'balances') IS DISTINCT FROM 'array' OR jsonb_typeof(p_balance->'postedLines') IS DISTINCT FROM 'array' OR jsonb_typeof(p_reconcile->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p_reconcile->'rows')<>4 OR NOT(p_report ?& ARRAY['balance','income','cashflow']) OR EXISTS(SELECT 1 FROM jsonb_each(p_report) r WHERE r.value->'available' IS DISTINCT FROM 'true'::jsonb) THEN RAISE EXCEPTION 'FIN_CLOSE_SNAPSHOT_INCOMPLETE';END IF;
 PERFORM public.jxc_fin_assert_balance(id) FROM public.fin_account_balance WHERE country_id=p_country AND book_id=p_book AND period_id=p_period;
 IF EXISTS(SELECT 1 FROM (SELECT l.account_id,l.aux_key,l.currency FROM public.fin_voucher_line l JOIN public.fin_voucher v ON v.country_id=l.country_id AND v.id=l.voucher_id WHERE v.country_id=p_country AND v.book_id=p_book AND v.voucher_date<=p.end_date AND v.status IN ('POSTED','REVERSED') UNION SELECT account_id,aux_key,currency FROM public.fin_opening_balance WHERE country_id=p_country AND book_id=p_book AND cutoff_date<p.start_date AND status='CONFIRMED') d WHERE NOT EXISTS(SELECT 1 FROM public.fin_account_balance b WHERE b.country_id=p_country AND b.book_id=p_book AND b.period_id=p_period AND b.account_id=d.account_id AND b.aux_key=d.aux_key AND b.currency=d.currency)) THEN RAISE EXCEPTION 'FIN_BALANCE_PROJECTION_MISSING';END IF;
 IF (SELECT count(DISTINCT x->>'type') FROM jsonb_array_elements(p_reconcile->'rows') x WHERE x->>'type' IN ('AR','AP','INVENTORY','CASH'))<>4 THEN RAISE EXCEPTION 'FIN_CLOSE_SNAPSHOT_INCOMPLETE';END IF;
 SELECT count(*) INTO expected_count FROM public.fin_account_balance WHERE country_id=p_country AND book_id=p_book AND period_id=p_period;
 IF jsonb_array_length(p_balance->'balances')<>expected_count THEN RAISE EXCEPTION 'FIN_CLOSE_BALANCE_MISMATCH';END IF;
 SELECT count(*) INTO bad_count FROM jsonb_array_elements(p_balance->'balances') x LEFT JOIN public.fin_account_balance b ON b.country_id=p_country AND b.book_id=p_book AND b.period_id=p_period AND b.id=(x->>'id')::bigint WHERE b.id IS NULL OR NOT(x ?& ARRAY['id','accountId','auxKey','currency','openingDebit','openingCredit','periodDebit','periodCredit','closingDebit','closingCredit','origClosing']) OR (x->>'accountId')::bigint IS DISTINCT FROM b.account_id OR x->>'auxKey' IS DISTINCT FROM b.aux_key OR x->>'currency' IS DISTINCT FROM b.currency OR (x->>'openingDebit')::numeric IS DISTINCT FROM b.opening_debit OR (x->>'openingCredit')::numeric IS DISTINCT FROM b.opening_credit OR (x->>'periodDebit')::numeric IS DISTINCT FROM b.period_debit OR (x->>'periodCredit')::numeric IS DISTINCT FROM b.period_credit OR (x->>'closingDebit')::numeric IS DISTINCT FROM b.closing_debit OR (x->>'closingCredit')::numeric IS DISTINCT FROM b.closing_credit OR (x->>'origClosing')::numeric IS DISTINCT FROM b.orig_closing;
 IF bad_count<>0 OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_balance->'balances') x)<>expected_count THEN RAISE EXCEPTION 'FIN_CLOSE_BALANCE_MISMATCH';END IF;
 IF EXISTS(SELECT 1 FROM public.fin_account_balance b WHERE b.country_id=p_country AND b.book_id=p_book AND b.period_id=p_period AND (b.closing_debit-b.closing_credit<>b.opening_debit-b.opening_credit+b.period_debit-b.period_credit)) THEN RAISE EXCEPTION 'FIN_CLOSE_BALANCE_MISMATCH';END IF;
 IF (SELECT coalesce(sum(closing_debit-closing_credit),0) FROM public.fin_account_balance WHERE country_id=p_country AND book_id=p_book AND period_id=p_period)<>0 THEN RAISE EXCEPTION 'FIN_CLOSE_UNBALANCED';END IF;
 SELECT count(*) INTO expected_count FROM public.fin_voucher_line l JOIN public.fin_voucher v ON v.country_id=l.country_id AND v.id=l.voucher_id WHERE v.country_id=p_country AND v.book_id=p_book AND v.period_id=p_period AND v.status IN ('POSTED','REVERSED');
 IF jsonb_array_length(p_balance->'postedLines')<>expected_count OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_balance->'postedLines') x)<>expected_count THEN RAISE EXCEPTION 'FIN_CLOSE_LINES_MISMATCH';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_balance->'postedLines') x LEFT JOIN public.fin_voucher_line l ON l.country_id=p_country AND l.book_id=p_book AND l.id=(x->>'id')::bigint LEFT JOIN public.fin_voucher v ON v.country_id=l.country_id AND v.id=l.voucher_id AND v.period_id=p_period WHERE v.id IS NULL OR NOT(x ?& ARRAY['id','debit','credit','accountId']) OR (x->>'debit')::numeric IS DISTINCT FROM l.debit OR (x->>'credit')::numeric IS DISTINCT FROM l.credit OR (x->>'accountId')::bigint IS DISTINCT FROM l.account_id) THEN RAISE EXCEPTION 'FIN_CLOSE_LINES_MISMATCH';END IF;
 IF jsonb_typeof(p_checks) IS DISTINCT FROM 'array' OR NOT(p_checks @> '[{"checkCode":"REPORT_CONFIG","result":"PASS"}]'::jsonb) THEN RAISE EXCEPTION 'FIN_CLOSE_CHECKS_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['UNPOSTED','UNBALANCED','EVENTS_OPEN','COST_PENDING','ALLOCATION_PENDING','STOCKTAKE_PENDING','RECON_DATA_MISSING','AR_DIFF','AP_DIFF','INV_DIFF','CASH_DIFF','CASHFLOW_MISSING','REPORT_CONFIG','NEXT_PERIOD']) c WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_checks) x WHERE x->>'checkCode'=c)) THEN RAISE EXCEPTION 'FIN_CLOSE_CHECKS_REQUIRED';END IF;
 FOR item IN SELECT * FROM jsonb_array_elements(p_checks) LOOP
  IF item->>'result' IS NULL OR item->>'result' NOT IN ('PASS','WAIVED') THEN RAISE EXCEPTION 'FIN_CLOSE_BLOCKED';END IF;
  IF item->>'result'='WAIVED' AND NOT EXISTS(SELECT 1 FROM public.fin_close_waiver w WHERE w.country_id=p_country AND w.book_id=p_book AND w.period_id=p_period AND w.close_generation=n AND w.check_code=item->>'checkCode' AND w.fingerprint=item->>'fingerprint') THEN RAISE EXCEPTION 'FIN_WAIVER_STALE';END IF;
 END LOOP;
 next_start:=p.end_date+1;SELECT id INTO next_id FROM public.fin_period WHERE country_id=p_country AND book_id=p_book AND start_date=next_start FOR UPDATE;
 IF next_id IS NULL THEN
  IF p.start_date<>date_trunc('month',p.start_date)::date OR p.end_date<>(date_trunc('month',p.start_date)+interval '1 month - 1 day')::date THEN RAISE EXCEPTION 'FIN_NEXT_PERIOD_REQUIRED';END IF;
  next_end:=(date_trunc('month',next_start)+interval '1 month - 1 day')::date;
  INSERT INTO public.fin_period(country_id,book_id,fiscal_year,period_no,start_date,end_date,status,created_by) VALUES(p_country,p_book,extract(year from next_start)::integer,extract(month from next_start)::integer,next_start,next_end,'OPEN',p_user) RETURNING id INTO next_id;
 ELSE
  IF EXISTS(SELECT 1 FROM public.fin_period WHERE id=next_id AND country_id=p_country AND status NOT IN ('OPEN','NOT_STARTED')) THEN RAISE EXCEPTION 'FIN_NEXT_PERIOD_NOT_OPEN';END IF;
  UPDATE public.fin_period SET status='OPEN',version=version+1,updated_by=p_user,updated_at=clock_timestamp() WHERE id=next_id AND country_id=p_country AND status='NOT_STARTED';
 END IF;
 INSERT INTO public.fin_close_generation(country_id,book_id,period_id,close_generation,source_fingerprint,checks,created_by) VALUES(p_country,p_book,p_period,n,p_fingerprint,p_checks,p_user);
 INSERT INTO public.fin_snapshot(country_id,book_id,period_id,close_generation,snapshot_type,content,source_versions,source_fingerprint,created_by) VALUES(p_country,p_book,p_period,n,'BALANCE',p_balance,p_sources,p_fingerprint,p_user),(p_country,p_book,p_period,n,'REPORT',p_report,p_sources,p_fingerprint,p_user),(p_country,p_book,p_period,n,'RECONCILE',p_reconcile,p_sources,p_fingerprint,p_user);
 UPDATE public.fin_period SET status='CLOSED',close_generation=n,closed_by=p_user,closed_at=clock_timestamp(),updated_by=p_user,updated_at=clock_timestamp(),version=version+1 WHERE country_id=p_country AND id=p_period;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_guard_biz_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE opening_txn inv_stock_txn;
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.source_type='OPENING_STOCK' AND NEW.event_type='INV_STOCK_CHANGED' THEN
   SELECT * INTO opening_txn FROM inv_stock_txn t WHERE t.country_id=NEW.country_id AND t.book_id=NEW.book_id AND t.source_type='OPENING_STOCK' AND t.source_line_id=NEW.source_id AND t.txn_type='OPENING_IN' AND t.seq=1 AND t.biz_date=NEW.biz_date;
   IF NOT FOUND OR NEW.event_seq<>1 OR NEW.payload IS DISTINCT FROM jsonb_build_object('warehouseId',opening_txn.warehouse_id,'productId',opening_txn.product_id,'sourceId',opening_txn.source_id,'sourceLineId',opening_txn.source_line_id) THEN RAISE EXCEPTION 'SYS_IMPORT_OPENING_SOURCE_MISMATCH' USING ERRCODE='23514';END IF;
   PERFORM jxc_assert_subledger_opening_fact('inv_stock_txn',to_jsonb(opening_txn));RETURN NEW;
  ELSIF NEW.source_type='SYS_REPORT_EXPORT' OR NEW.event_type='SYS_REPORT_EXPORT_REQUESTED' THEN
   IF NEW.source_type<>'SYS_REPORT_EXPORT' OR NEW.event_type<>'SYS_REPORT_EXPORT_REQUESTED' OR NEW.event_seq<>1 OR
    NOT EXISTS(SELECT 1 FROM sys_export_job WHERE country_id=NEW.country_id AND book_id=NEW.book_id AND id=NEW.source_id)
   THEN RAISE EXCEPTION 'JXC_JOB_SOURCE_REQUIRED' USING ERRCODE='P0001';END IF;
   PERFORM id FROM fin_book WHERE country_id=NEW.country_id AND id=NEW.book_id FOR SHARE;
  ELSE PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,NEW.biz_date);END IF;
  RETURN NEW;
 ELSIF TG_OP='DELETE' THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001';
 ELSIF ROW(NEW.id,NEW.country_id,NEW.book_id,NEW.event_type,NEW.source_type,NEW.source_id,NEW.event_seq,NEW.payload,NEW.biz_date,NEW.occurred_at)
  IS DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.book_id,OLD.event_type,OLD.source_type,OLD.source_id,OLD.event_seq,OLD.payload,OLD.biz_date,OLD.occurred_at)
 THEN
  IF NOT(OLD.source_type='SYS_REPORT_EXPORT' AND OLD.event_type='SYS_REPORT_EXPORT_REQUESTED') THEN PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.biz_date);END IF;
  RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_guard_fin_event_result()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE policy fin_mapping_template; evt sys_biz_event; voucher fin_voucher;
BEGIN
 SELECT * INTO policy FROM fin_mapping_template WHERE country_id=NEW.country_id AND id=NEW.mapping_template_id;
 SELECT * INTO evt FROM sys_biz_event WHERE country_id=NEW.country_id AND id=NEW.event_id;
 IF policy.status IS DISTINCT FROM 'ACTIVE' OR policy.event_type IS DISTINCT FROM evt.event_type
    OR policy.book_id IS DISTINCT FROM NEW.book_id OR evt.book_id IS DISTINCT FROM NEW.book_id
    OR policy.version_no IS DISTINCT FROM NEW.mapping_version OR NEW.source_event_version IS DISTINCT FROM evt.event_seq THEN
  RAISE EXCEPTION 'FIN_EVENT_INTERPRETATION_INVALID';
 END IF;
 IF NEW.status='NO_VOUCHER' AND policy.accounting_mode IS DISTINCT FROM 'NO_VOUCHER' THEN
  IF policy.accounting_mode IS DISTINCT FROM 'VOUCHER'
     OR NEW.reason IS DISTINCT FROM 'SOURCE_CONFIRMATION_ZERO_POSTING'
     OR NEW.voucher_id IS NOT NULL OR NEW.fact_hash IS NULL OR NEW.fact_hash !~ '^[a-f0-9]{64}$'
     OR NOT EXISTS (
       SELECT 1 FROM sys_biz_event_consume c
       WHERE c.country_id=NEW.country_id AND c.book_id=NEW.book_id AND c.event_id=NEW.event_id
         AND c.consumer='FIN_VOUCHER' AND c.status='PROCESSING'
         -- The original consumer marks its locked effect intent in this very
         -- transaction. A committed lease or another consumer is insufficient.
         AND c.xmin::text::numeric=mod(pg_current_xact_id()::text::numeric,4294967296)
     ) THEN
   RAISE EXCEPTION 'FIN_EVENT_INTERPRETATION_INVALID';
  END IF;
 ELSIF NEW.status='GENERATED' AND policy.accounting_mode IS DISTINCT FROM 'VOUCHER' THEN
  RAISE EXCEPTION 'FIN_EVENT_INTERPRETATION_INVALID';
 END IF;
 IF NEW.voucher_id IS NOT NULL THEN
  SELECT * INTO voucher FROM fin_voucher WHERE country_id=NEW.country_id AND id=NEW.voucher_id;
  IF voucher.source_event_id IS DISTINCT FROM NEW.event_id OR voucher.mapping_template_id IS DISTINCT FROM NEW.mapping_template_id OR voucher.mapping_version IS DISTINCT FROM NEW.mapping_version THEN RAISE EXCEPTION 'FIN_EVENT_INTERPRETATION_INVALID'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_guard_mapping()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='INSERT' THEN RETURN NEW; END IF;
 IF OLD.status<>'NEED_REVIEW' AND (TG_OP='DELETE' OR ROW(NEW.book_id,NEW.event_type,NEW.version_no,NEW.accounting_mode,NEW.no_voucher_reason,NEW.source_template_item_id,NEW.reviewed_by,NEW.reviewed_at) IS DISTINCT FROM ROW(OLD.book_id,OLD.event_type,OLD.version_no,OLD.accounting_mode,OLD.no_voucher_reason,OLD.source_template_item_id,OLD.reviewed_by,OLD.reviewed_at)) THEN RAISE EXCEPTION 'JXC_REVIEWED_MAPPING_IMMUTABLE'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF OLD.status='ACTIVE' AND NEW.status NOT IN('ACTIVE','RETIRED') OR OLD.status='RETIRED' AND NEW.status<>'RETIRED' THEN RAISE EXCEPTION 'JXC_REVIEWED_MAPPING_IMMUTABLE'; END IF;
 IF ROW(NEW.id,NEW.country_id,NEW.book_id,NEW.event_type,NEW.version_no,NEW.created_by,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.book_id,OLD.event_type,OLD.version_no,OLD.created_by,OLD.created_at) THEN RAISE EXCEPTION 'JXC_MAPPING_IDENTITY_IMMUTABLE'; END IF;
 RETURN NEW;
END $function$

