CREATE OR REPLACE FUNCTION public.jxc_import_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_TABLE_NAME='sys_import_batch' AND TG_OP='UPDATE' THEN
  IF OLD.status IN ('COMPLETED','CANCELLED') OR ROW(NEW.id,NEW.country_id,NEW.import_type,NEW.template_version,NEW.file_sha256,NEW.cutoff_date,NEW.requested_by,NEW.total_rows,NEW.valid_rows,NEW.error_rows,NEW.created_at,NEW.source_file_text,NEW.content_sha256,NEW.hash_basis,NEW.attempt_no,NEW.previous_batch_id)
   IS DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.import_type,OLD.template_version,OLD.file_sha256,OLD.cutoff_date,OLD.requested_by,OLD.total_rows,OLD.valid_rows,OLD.error_rows,OLD.created_at,OLD.source_file_text,OLD.content_sha256,OLD.hash_basis,OLD.attempt_no,OLD.previous_batch_id)
  THEN RAISE EXCEPTION 'SYS_IMPORT_IMMUTABLE'; END IF;
  RETURN NEW;
 ELSIF TG_TABLE_NAME='sys_import_row' AND TG_OP='UPDATE' THEN
  IF OLD.target_id IS NOT NULL OR ROW(NEW.id,NEW.country_id,NEW.batch_id,NEW.row_no,NEW.raw,NEW.normalized,NEW.source_key,NEW.errors)
   IS DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.batch_id,OLD.row_no,OLD.raw,OLD.normalized,OLD.source_key,OLD.errors)
  THEN RAISE EXCEPTION 'SYS_IMPORT_IMMUTABLE'; END IF;
  RETURN NEW;
 END IF;
 RAISE EXCEPTION 'SYS_IMPORT_IMMUTABLE';
END $function$

CREATE OR REPLACE FUNCTION public.jxc_inbound_confirmation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE source record;BEGIN
 SELECT * INTO source FROM cst_inbound_cost WHERE country_id=NEW.country_id AND id=NEW.cost_id;
 IF source.base_purchase_amount IS NOT NULL AND (NEW.base_purchase_amount<>source.base_purchase_amount OR NEW.rate IS DISTINCT FROM source.rate OR NEW.rate_id IS DISTINCT FROM source.rate_id OR NEW.rate_version IS DISTINCT FROM source.rate_version) THEN RAISE EXCEPTION 'CST_COMPLETE_SNAPSHOT_IMMUTABLE';END IF;
 IF source.base_purchase_amount IS NULL AND source.src_amount IS NOT NULL AND (NEW.rate IS NULL OR NEW.rate<=0 OR NEW.base_purchase_amount<>round(source.src_amount*NEW.rate,4)) THEN RAISE EXCEPTION 'CST_COMPLETION_RATE_MISMATCH';END IF;
 IF NEW.unit_cost<>round(NEW.base_purchase_amount/source.qty,12) THEN RAISE EXCEPTION 'CST_COMPLETION_UNIT_MISMATCH';END IF;RETURN NEW;END $function$

CREATE OR REPLACE FUNCTION public.jxc_inventory_conservation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c bigint;w bigint;p bigint;hand numeric;frozen numeric;reserved numeric;batch_hand numeric;batch_frozen numeric;reservation_qty numeric;
BEGIN
 c:=COALESCE(NEW.country_id,OLD.country_id);w:=COALESCE(NEW.warehouse_id,OLD.warehouse_id);p:=COALESCE(NEW.product_id,OLD.product_id);
 SELECT on_hand_qty,frozen_qty,reserved_qty INTO hand,frozen,reserved FROM inv_stock_summary WHERE country_id=c AND warehouse_id=w AND product_id=p;
 SELECT coalesce(sum(on_hand_qty),0),coalesce(sum(frozen_qty),0) INTO batch_hand,batch_frozen FROM inv_batch_balance WHERE country_id=c AND warehouse_id=w AND product_id=p;
 SELECT coalesce(sum(qty-consumed_qty-released_qty),0) INTO reservation_qty FROM inv_reservation WHERE country_id=c AND warehouse_id=w AND product_id=p;
 IF hand IS NOT NULL AND (hand<>batch_hand OR frozen<>batch_frozen OR reserved<>reservation_qty) THEN RAISE EXCEPTION 'INV_CONSERVATION_VIOLATION';END IF;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_inventory_dated_fact_guard()
 RETURNS trigger
 LANGUAGE plpgsql
