CREATE OR REPLACE FUNCTION public.jxc_json_id_value_safe(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item jsonb; number_value numeric;
BEGIN
  IF jsonb_typeof(value) = 'number' THEN
    number_value := (value #>> '{}')::numeric;
    RETURN number_value BETWEEN 1 AND 9007199254740991 AND trunc(number_value) = number_value;
  ELSIF jsonb_typeof(value) = 'array' THEN
    FOR item IN SELECT jsonb_array_elements(value) LOOP
      IF NOT jxc_json_id_value_safe(item) THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
  END IF;
  RETURN jsonb_typeof(value) IN ('null', 'string');
END
$function$

CREATE OR REPLACE FUNCTION public.jxc_json_ids_safe(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE field record; item jsonb;
BEGIN
  IF jsonb_typeof(value) = 'object' THEN
    FOR field IN SELECT key, val FROM jsonb_each(value) AS fields(key, val) LOOP
      IF field.key ~ '(^id$|_id$|Id$|_ids$|Ids$)' AND NOT jxc_json_id_value_safe(field.val) THEN RETURN false; END IF;
      IF NOT jxc_json_ids_safe(field.val) THEN RETURN false; END IF;
    END LOOP;
  ELSIF jsonb_typeof(value) = 'array' THEN
    FOR item IN SELECT jsonb_array_elements(value) LOOP
      IF NOT jxc_json_ids_safe(item) THEN RETURN false; END IF;
    END LOOP;
  END IF;
  RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.jxc_lgs_receipt_confirmation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF OLD.status='CONFIRMED' AND ROW(NEW.status,NEW.confirmed_by,NEW.confirmed_at) IS DISTINCT FROM ROW(OLD.status,OLD.confirmed_by,OLD.confirmed_at) THEN RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE';END IF;
 IF NEW.status='CONFIRMED' AND OLD.status<>'CONFIRMED' AND (OLD.status<>'DRAFT' OR NEW.confirmed_by IS NULL OR NEW.confirmed_at IS NULL) THEN RAISE EXCEPTION 'LGS_RECEIPT_CONFIRMATION_REQUIRED';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_next_doc_number(selected_country bigint, selected_type text, document_date date)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE rule sys_doc_number_rule;bucket_value text;issued bigint;date_part text;
BEGIN
 IF selected_country IS DISTINCT FROM jxc_current_country_id() OR document_date IS NULL THEN RAISE EXCEPTION 'SYS_COUNTRY_REQUIRED';END IF;
 SELECT * INTO rule FROM sys_doc_number_rule WHERE country_id=selected_country AND doc_type=selected_type FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SYS_CONFIG_MISSING: document number rule';END IF;
 bucket_value:=CASE rule.reset_period WHEN 'DAY' THEN to_char(document_date,'YYYYMMDD') WHEN 'MONTH' THEN to_char(document_date,'YYYYMM') WHEN 'YEAR' THEN to_char(document_date,'YYYY') ELSE '*' END;
 INSERT INTO sys_doc_number_counter(country_id,doc_type,bucket,last_value) VALUES(selected_country,selected_type,bucket_value,1)
 ON CONFLICT(country_id,doc_type,bucket) DO UPDATE SET last_value=sys_doc_number_counter.last_value+1 RETURNING last_value INTO issued;
 IF length(issued::text)>rule.sequence_width THEN RAISE EXCEPTION 'SYS_NUMBER_EXHAUSTED';END IF;
 date_part:=CASE rule.date_pattern WHEN 'yyyyMMdd' THEN to_char(document_date,'YYYYMMDD') WHEN 'yyyyMM' THEN to_char(document_date,'YYYYMM') WHEN 'yyyy' THEN to_char(document_date,'YYYY') ELSE '' END;
 RETURN rule.prefix||date_part||lpad(issued::text,rule.sequence_width,'0');
END $function$

CREATE OR REPLACE FUNCTION public.jxc_opening_import_allowed(selected_country bigint, document_date date)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE batch_setting text;allowed boolean;
BEGIN
 batch_setting:=current_setting('app.opening_import_batch',true);
 IF document_date IS NULL OR batch_setting IS NULL OR batch_setting !~ '^[1-9][0-9]{0,15}$' OR to_regclass('public.sys_import_batch') IS NULL THEN RETURN false;END IF;
 EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.sys_import_batch WHERE country_id=$1 AND id=$2 AND status=''VALIDATED'' AND left(import_type,8)=''OPENING_'' AND cutoff_date IS NOT NULL AND $3<=cutoff_date)' INTO allowed USING selected_country,batch_setting::bigint,document_date;
 RETURN allowed;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_pending_cost_completion_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ DECLARE original record;BEGIN
 IF TG_TABLE_NAME='cst_transfer_completion' THEN SELECT book_id,amount INTO original FROM cst_transfer_cost WHERE country_id=NEW.country_id AND id=NEW.transfer_cost_id;
 ELSIF TG_TABLE_NAME='cst_transfer_part_completion' THEN SELECT t.book_id,p.amount INTO original FROM cst_transfer_cost_part p JOIN cst_transfer_cost t ON t.country_id=p.country_id AND t.id=p.transfer_cost_id WHERE p.country_id=NEW.country_id AND p.transfer_cost_id=NEW.transfer_cost_id AND p.batch_id=NEW.batch_id;
 ELSIF TG_TABLE_NAME='cst_movement_completion' THEN SELECT book_id,amount_change amount INTO original FROM cst_valuation_movement WHERE country_id=NEW.country_id AND id=NEW.movement_id;
 ELSE SELECT c.book_id,l.amount INTO original FROM cst_transfer_loss l JOIN cst_cogs c ON c.country_id=l.country_id AND c.id=l.cogs_id WHERE l.country_id=NEW.country_id AND l.id=NEW.loss_id;END IF;
 IF original.book_id<>NEW.book_id OR original.amount IS NOT NULL THEN RAISE EXCEPTION 'CST_COMPLETE_SNAPSHOT_IMMUTABLE';END IF;RETURN NEW;END $function$

CREATE OR REPLACE FUNCTION public.jxc_period_closing_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF current_user='${runtimeRole}' THEN
  IF TG_OP='INSERT' AND (NEW.status NOT IN ('OPEN','NOT_STARTED') OR NEW.close_generation<>0 OR NEW.closed_by IS NOT NULL OR NEW.closed_at IS NOT NULL) THEN RAISE EXCEPTION 'FIN_PERIOD_CONTROLLED_TRANSITION';END IF;
  IF TG_OP='UPDATE' AND (ROW(NEW.status,NEW.close_generation,NEW.closed_by,NEW.closed_at,NEW.country_id,NEW.book_id,NEW.fiscal_year,NEW.period_no,NEW.start_date,NEW.end_date) IS DISTINCT FROM ROW(OLD.status,OLD.close_generation,OLD.closed_by,OLD.closed_at,OLD.country_id,OLD.book_id,OLD.fiscal_year,OLD.period_no,OLD.start_date,OLD.end_date)) THEN RAISE EXCEPTION 'FIN_PERIOD_CONTROLLED_TRANSITION';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_purchase_order_header_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE source record;
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.country_id,NEW.book_id,NEW.entity_id,NEW.supplier_id,NEW.currency,NEW.doc_no,NEW.source_country,NEW.order_date,NEW.biz_date,NEW.expected_date,NEW.payment_terms,NEW.prepay_ratio,NEW.term_days,NEW.total_qty,NEW.total_amount,NEW.tax_amount) IS NOT DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.book_id,OLD.entity_id,OLD.supplier_id,OLD.currency,OLD.doc_no,OLD.source_country,OLD.order_date,OLD.biz_date,OLD.expected_date,OLD.payment_terms,OLD.prepay_ratio,OLD.term_days,OLD.total_qty,OLD.total_amount,OLD.tax_amount) AND (NEW.status=OLD.status OR NEW.status IN ('CONFIRMED','PARTIAL_DELIVERED','DELIVERED','CLOSED')) THEN RETURN NEW;END IF;
 -- Header edits race AP through exactly the source rows locked by SupplyApi.
 FOR source IN SELECT id FROM pur_order_line WHERE country_id=OLD.country_id AND order_id=OLD.id ORDER BY id FOR UPDATE LOOP
  IF jxc_ap_purchase_order_has_history(OLD.country_id,source.id) THEN RAISE EXCEPTION 'PUR_SOURCE_IN_USE: original purchase document has AP history' USING ERRCODE='23514';END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_purchase_order_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE claimed_q numeric; claimed_a numeric;
BEGIN
 IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['cancelled_qty','qualified_qty','pending_inspect_qty','damaged_qty','exported_qty','shipped_qty','arrived_mx_qty','returned_qty','domestic_returned_qty','overseas_returned_qty','version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['cancelled_qty','qualified_qty','pending_inspect_qty','damaged_qty','exported_qty','shipped_qty','arrived_mx_qty','returned_qty','domestic_returned_qty','overseas_returned_qty','version']) THEN
  IF jxc_ap_purchase_order_has_history(OLD.country_id,OLD.id) THEN RAISE EXCEPTION 'PUR_SOURCE_IN_USE: original purchase economics have AP history' USING ERRCODE='23514'; END IF;
 END IF;
 IF TG_OP='UPDATE' AND NEW.cancelled_qty IS DISTINCT FROM OLD.cancelled_qty THEN
  SELECT coalesce(sum(qty),0),coalesce(sum(amount),0) INTO claimed_q,claimed_a FROM ap_source_claim WHERE country_id=OLD.country_id AND source_type='PUR_ORDER_LINE_BASE' AND source_id=OLD.id AND effective;
  IF claimed_q>NEW.base_qty-NEW.cancelled_qty OR claimed_a>round((NEW.base_qty-NEW.cancelled_qty)*NEW.unit_price/NEW.factor,4) THEN
   RAISE EXCEPTION 'PUR_SOURCE_IN_USE: cancellation would remove an effective payable quantity or amount' USING ERRCODE='23514';
  END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_purchase_receipt_header_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE source record; economic_change boolean;
BEGIN
 economic_change:=TG_OP='DELETE' OR ROW(NEW.id,NEW.country_id,NEW.book_id,NEW.entity_id,NEW.order_id,NEW.supplier_id,NEW.doc_no,NEW.biz_date,NEW.receipt_date) IS DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.book_id,OLD.entity_id,OLD.order_id,OLD.supplier_id,OLD.doc_no,OLD.biz_date,OLD.receipt_date);
 IF NOT economic_change AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW;END IF;
 FOR source IN SELECT id FROM pur_domestic_receipt_line WHERE country_id=OLD.country_id AND receipt_id=OLD.id ORDER BY id FOR UPDATE LOOP
  IF (economic_change AND jxc_ap_receipt_has_history(OLD.country_id,source.id)) OR (NEW.status<>'CONFIRMED' AND jxc_ap_receipt_has_effective_claims(OLD.country_id,source.id)) THEN
   RAISE EXCEPTION 'PUR_SOURCE_IN_USE: receipt is retained by payable history or effective claims' USING ERRCODE='23514';
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_purchase_receipt_source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR ROW(NEW.id,NEW.country_id,NEW.receipt_id,NEW.order_line_id,NEW.product_id,NEW.qualified_qty,NEW.pending_inspect_qty,NEW.damaged_qty) IS DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.receipt_id,OLD.order_line_id,OLD.product_id,OLD.qualified_qty,OLD.pending_inspect_qty,OLD.damaged_qty) THEN
  IF jxc_ap_receipt_has_history(OLD.country_id,OLD.id) THEN RAISE EXCEPTION 'PUR_SOURCE_IN_USE: original receipt economics have AP history' USING ERRCODE='23514';END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_reopen_period(p_country bigint, p_book bigint, p_period bigint, p_user bigint, p_reason text, p_dependencies jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p public.fin_period;refs jsonb;waivers jsonb;log_id bigint;
BEGIN
 IF p_country IS DISTINCT FROM public.jxc_current_country_id() THEN RAISE EXCEPTION 'SYS_COUNTRY_REQUIRED';END IF;
 IF length(btrim(coalesce(p_reason,'')))=0 OR length(p_reason)>1000 THEN RAISE EXCEPTION 'FIN_REOPEN_REASON_REQUIRED';END IF;
 PERFORM 1 FROM public.fin_book WHERE country_id=p_country AND id=p_book AND status='ACTIVE' FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'FIN_BOOK_NOT_ACTIVE';END IF;
 SELECT * INTO p FROM public.fin_period WHERE country_id=p_country AND book_id=p_book AND id=p_period FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'FIN_PERIOD_NOT_FOUND';END IF;
 IF p.status<>'CLOSED' THEN RAISE EXCEPTION 'FIN_PERIOD_NOT_CLOSED';END IF;
 IF EXISTS(SELECT 1 FROM public.fin_period WHERE country_id=p_country AND book_id=p_book AND start_date>p.end_date AND status='CLOSED') THEN RAISE EXCEPTION 'FIN_LATER_CLOSED';END IF;
 SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO refs FROM public.fin_snapshot WHERE country_id=p_country AND book_id=p_book AND period_id=p_period AND close_generation=p.close_generation;
 SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO waivers FROM public.fin_close_waiver WHERE country_id=p_country AND book_id=p_book AND period_id=p_period AND close_generation<=p.close_generation;
 INSERT INTO public.fin_reopen_log(country_id,book_id,period_id,previous_generation,reason,snapshot_refs,dependencies,invalidated_waiver_ids,operated_by) VALUES(p_country,p_book,p_period,p.close_generation,p_reason,refs,p_dependencies,waivers,p_user) RETURNING id INTO log_id;
 UPDATE public.fin_period SET status='OPEN',closed_by=NULL,closed_at=NULL,updated_by=p_user,updated_at=clock_timestamp(),version=version+1 WHERE country_id=p_country AND id=p_period;
 RETURN log_id;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_return_origin_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE no_origin boolean;
BEGIN
 SELECT no_origin_flag INTO no_origin FROM rtn_sales_return WHERE country_id=NEW.country_id AND id=NEW.return_id;
 IF no_origin AND (NEW.outbound_line_id IS NOT NULL OR NEW.order_line_id IS NOT NULL OR NEW.cost_source NOT IN ('BATCH','LATEST_INBOUND') OR NEW.cost_source IS NULL OR NEW.cost_snapshot_id IS NULL OR NEW.origin_batch_id IS NULL) THEN RAISE EXCEPTION 'RTN_COST_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
 IF NOT no_origin AND (NEW.outbound_line_id IS NULL OR NEW.order_line_id IS NULL) THEN RAISE EXCEPTION 'RTN_ORIGIN_REQUIRED' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_return_settlement_balanced()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE sid bigint; expected numeric; actual numeric;
BEGIN
 sid:=CASE TG_TABLE_NAME WHEN 'rtn_sales_settlement' THEN (to_jsonb(NEW)->>'id')::bigint ELSE (to_jsonb(NEW)->>'settlement_id')::bigint END;
 SELECT total_amount INTO expected FROM rtn_sales_settlement WHERE country_id=NEW.country_id AND id=sid;
 SELECT coalesce(sum(amount),0) INTO actual FROM rtn_sales_settlement_line WHERE country_id=NEW.country_id AND settlement_id=sid;
 IF expected IS DISTINCT FROM actual THEN RAISE EXCEPTION 'RETURN_SETTLEMENT_AMOUNT_INCONSISTENT' USING ERRCODE='23514';END IF;RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_return_settlement_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE l record;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE' USING ERRCODE='23514';END IF;
 SELECT inspected_qty,outbound_line_id INTO l FROM rtn_sales_return_line WHERE country_id=NEW.country_id AND id=NEW.return_line_id AND return_id=NEW.return_id;
 IF l IS NULL OR NEW.qty<>l.inspected_qty OR NEW.outbound_line_id IS DISTINCT FROM l.outbound_line_id THEN RAISE EXCEPTION 'RETURN_SETTLEMENT_SOURCE_MISMATCH' USING ERRCODE='23503';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_return_source_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE h record; source record;
BEGIN
 SELECT * INTO h FROM rtn_sales_return WHERE country_id=NEW.country_id AND id=NEW.return_id;
 IF NOT h.no_origin_flag THEN
  SELECT o.order_id,o.warehouse_id,l.book_id,l.order_line_id,l.product_id,l.outbound_id INTO source FROM sal_outbound_line l JOIN sal_outbound o ON o.country_id=l.country_id AND o.id=l.outbound_id WHERE l.country_id=NEW.country_id AND l.id=NEW.outbound_line_id;
  IF source IS NULL OR ROW(source.book_id,source.order_id,source.outbound_id,source.order_line_id,source.product_id) IS DISTINCT FROM ROW(h.book_id,h.order_id,h.outbound_id,NEW.order_line_id,NEW.product_id) THEN RAISE EXCEPTION 'RETURN_SOURCE_MISMATCH' USING ERRCODE='23503';END IF;
  IF NEW.origin_batch_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM sal_outbound_batch WHERE country_id=NEW.country_id AND outbound_line_id=NEW.outbound_line_id AND batch_id=NEW.origin_batch_id) THEN RAISE EXCEPTION 'RETURN_BATCH_SOURCE_MISMATCH' USING ERRCODE='23503';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM cst_inbound_cost c JOIN inv_batch b ON b.country_id=c.country_id AND b.id=c.batch_id WHERE c.country_id=NEW.country_id AND c.id=NEW.cost_snapshot_id AND c.batch_id=NEW.origin_batch_id AND c.book_id=h.book_id AND c.product_id=NEW.product_id AND c.warehouse_id=h.return_warehouse_id AND b.book_id=h.book_id AND b.product_id=NEW.product_id) THEN RAISE EXCEPTION 'RETURN_COST_SOURCE_MISMATCH' USING ERRCODE='23503';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_sales_allocation_complete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE row_line record;line_id bigint;c bigint;
BEGIN
 c:=coalesce(NEW.country_id,OLD.country_id);IF TG_TABLE_NAME='sal_order_line' THEN line_id:=coalesce(NEW.id,OLD.id);ELSE line_id:=coalesce(NEW.order_line_id,OLD.order_line_id);END IF;
 SELECT id,base_qty INTO row_line FROM sal_order_line WHERE country_id=c AND id=line_id FOR UPDATE;
 IF FOUND AND (SELECT coalesce(sum(alloc_qty),0) FROM sal_order_alloc WHERE country_id=c AND order_line_id=line_id)<>row_line.base_qty THEN RAISE EXCEPTION 'SAL_ALLOCATION_NOT_BALANCED' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_sales_children_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent record; parent_id bigint;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001'; END IF;
 parent_id:=(to_jsonb(NEW)->>TG_ARGV[1])::bigint;
 EXECUTE format('SELECT country_id,book_id,%I AS biz_date FROM %I WHERE country_id=$1 AND id=$2',TG_ARGV[2],TG_ARGV[0]) INTO parent USING NEW.country_id,parent_id;
 IF parent IS NOT NULL THEN PERFORM jxc_assert_period_open(parent.country_id,parent.book_id,parent.biz_date); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_sales_date_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d date;old_d date;
BEGIN
 d:=(to_jsonb(NEW)->>TG_ARGV[0])::date;
 IF TG_OP='INSERT' AND ((TG_TABLE_NAME='ar_receivable' AND to_jsonb(NEW)->>'source_type'='OPENING_AR') OR (TG_TABLE_NAME='ar_credit_note' AND to_jsonb(NEW)->>'source_type'='OPENING_ADVANCE')) THEN
  PERFORM jxc_assert_subledger_opening_fact(TG_TABLE_NAME,to_jsonb(NEW));RETURN NEW;
 END IF;
 IF TG_OP='INSERT' THEN PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,d);
 ELSIF (to_jsonb(NEW)-string_to_array(TG_ARGV[1],',')) IS DISTINCT FROM (to_jsonb(OLD)-string_to_array(TG_ARGV[1],',')) THEN
  old_d:=(to_jsonb(OLD)->>TG_ARGV[0])::date;PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,old_d);PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,d);
  IF TG_ARGV[2]='immutable' THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_sales_order_child_economics()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE parent sal_order%ROWTYPE; economic_change boolean; progress_keys text[];
BEGIN
 SELECT * INTO parent FROM sal_order WHERE country_id=COALESCE(NEW.country_id,OLD.country_id) AND id=COALESCE(NEW.order_id,OLD.order_id) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SAL_ORDER_SOURCE_MISSING' USING ERRCODE='23503'; END IF;
 IF TG_TABLE_NAME='sal_order_line' THEN progress_keys:=ARRAY['outbound_qty','cancelled_qty','signed_qty','returned_qty','claimed_qty','version'];
 ELSE progress_keys:=ARRAY['outbound_qty','cancelled_qty','version']; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.country_id,NEW.book_id,NEW.order_id) IS DISTINCT FROM ROW(OLD.id,OLD.country_id,OLD.book_id,OLD.order_id) THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001'; END IF;
 IF TG_TABLE_NAME='sal_order_alloc' AND TG_OP='UPDATE' AND ROW(to_jsonb(NEW)->>'order_line_id',to_jsonb(NEW)->>'warehouse_id') IS DISTINCT FROM ROW(to_jsonb(OLD)->>'order_line_id',to_jsonb(OLD)->>'warehouse_id') THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001'; END IF;
 economic_change:=TG_OP IN ('INSERT','DELETE') OR (to_jsonb(NEW)-progress_keys) IS DISTINCT FROM (to_jsonb(OLD)-progress_keys);
 IF economic_change THEN
  IF parent.approval_status<>'DRAFT' THEN RAISE EXCEPTION 'SAL_ORDER_NOT_DRAFT' USING ERRCODE='P0001'; END IF;
  PERFORM jxc_assert_period_open(parent.country_id,parent.book_id,parent.order_date);
  IF TG_OP='DELETE' AND ((to_jsonb(OLD)->>'outbound_qty')::numeric>0 OR (to_jsonb(OLD)->>'cancelled_qty')::numeric>0) THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001'; END IF;
  IF TG_TABLE_NAME='sal_order_line' AND TG_OP='UPDATE' AND OLD.outbound_qty>0 AND
   (to_jsonb(NEW)-ARRAY['qty','base_qty','line_amount','line_no','outbound_qty','cancelled_qty','signed_qty','returned_qty','claimed_qty','version']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['qty','base_qty','line_amount','line_no','outbound_qty','cancelled_qty','signed_qty','returned_qty','claimed_qty','version']) THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001'; END IF;
 END IF;
 IF TG_OP<>'DELETE' AND NEW.book_id<>parent.book_id THEN RAISE EXCEPTION 'SAL_ORDER_BOOK_MISMATCH' USING ERRCODE='23503'; END IF;
 IF TG_TABLE_NAME='sal_order_alloc' AND TG_OP<>'DELETE' AND NOT EXISTS(SELECT 1 FROM org_warehouse w WHERE w.country_id=NEW.country_id AND w.id=(to_jsonb(NEW)->>'warehouse_id')::bigint AND w.entity_id=parent.entity_id) THEN RAISE EXCEPTION 'SAL_ALLOC_WAREHOUSE_MISMATCH' USING ERRCODE='23503'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_sales_outbound_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE head sal_outbound%ROWTYPE;
BEGIN
 SELECT * INTO head FROM sal_outbound WHERE country_id=COALESCE(NEW.country_id,OLD.country_id) AND id=COALESCE(NEW.outbound_id,OLD.outbound_id) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SAL_OUTBOUND_SOURCE_MISMATCH' USING ERRCODE='23503'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM sal_order_alloc a JOIN sal_order_line l ON l.country_id=a.country_id AND l.id=a.order_line_id
  WHERE a.country_id=NEW.country_id AND a.id=NEW.alloc_id AND a.book_id=NEW.book_id AND a.order_id=head.order_id AND a.warehouse_id=head.warehouse_id
   AND l.id=NEW.order_line_id AND l.book_id=NEW.book_id AND l.order_id=head.order_id AND l.product_id=NEW.product_id AND head.book_id=NEW.book_id)
 THEN RAISE EXCEPTION 'SAL_OUTBOUND_SOURCE_MISMATCH' USING ERRCODE='23503'; END IF;
 IF NEW.batch_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM inv_batch b JOIN inv_batch_balance bb ON bb.country_id=b.country_id AND bb.batch_id=b.id AND bb.product_id=b.product_id
  WHERE b.country_id=NEW.country_id AND b.id=NEW.batch_id AND b.book_id=NEW.book_id AND b.product_id=NEW.product_id AND bb.warehouse_id=head.warehouse_id)
 THEN RAISE EXCEPTION 'SAL_BATCH_SOURCE_MISMATCH' USING ERRCODE='23503'; END IF;
 IF NEW.cogs_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM cst_cogs c WHERE c.country_id=NEW.country_id AND c.id=NEW.cogs_id AND c.book_id=NEW.book_id AND c.product_id=NEW.product_id AND c.warehouse_id=head.warehouse_id AND c.source_type='SAL_OUTBOUND' AND c.source_line_id=NEW.id AND c.qty=NEW.qty)
 THEN RAISE EXCEPTION 'SAL_COGS_SOURCE_MISMATCH' USING ERRCODE='23503'; END IF;
 IF TG_OP='UPDATE' AND head.status<>'DRAFT' AND (to_jsonb(NEW)-ARRAY['receivable_id','version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['receivable_id','version']) THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001'; END IF;
 IF TG_OP='INSERT' OR (to_jsonb(NEW)-ARRAY['receivable_id','version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['receivable_id','version']) THEN PERFORM jxc_assert_period_open(head.country_id,head.book_id,head.biz_date); END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_sales_sign_line_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE head sal_sign%ROWTYPE; out_qty numeric;
BEGIN
 IF TG_OP='DELETE' OR TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['diff_status','resolution']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['diff_status','resolution']) THEN RAISE EXCEPTION 'JXC_IMMUTABLE_FACT' USING ERRCODE='P0001'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO head FROM sal_sign WHERE country_id=NEW.country_id AND id=NEW.sign_id;
  SELECT l.qty INTO out_qty FROM sal_outbound_line l WHERE l.country_id=NEW.country_id AND l.id=NEW.outbound_line_id AND l.book_id=head.book_id AND l.outbound_id=head.outbound_id;
  IF NOT FOUND OR NEW.signed_qty>out_qty THEN RAISE EXCEPTION 'SAL_SIGN_SOURCE_MISMATCH' USING ERRCODE='23503'; END IF;
  PERFORM jxc_assert_period_open(head.country_id,head.book_id,head.biz_date);
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_set_write_mode(p_mode text, p_expected_epoch bigint, p_batch_id uuid, p_operator text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE current_state public.sys_write_control%ROWTYPE;
BEGIN
 IF p_mode IS NULL OR p_mode NOT IN ('OPEN','FROZEN') OR p_expected_epoch IS NULL OR p_batch_id IS NULL
  OR p_operator IS NULL OR length(btrim(p_operator)) NOT BETWEEN 1 AND 200
  OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 1000 THEN
  RAISE EXCEPTION 'SYS_WRITE_CONTROL_INVALID' USING ERRCODE='22023';
 END IF;
 SELECT * INTO current_state FROM public.sys_write_control WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'SYS_WRITE_CONTROL_MISSING' USING ERRCODE='P0001'; END IF;
 -- A lost response may retry the exact transition using its original expected epoch.
 IF current_state.mode=p_mode AND current_state.batch_id=p_batch_id
   AND current_state.operator=p_operator AND current_state.reason=p_reason
   AND current_state.epoch=p_expected_epoch+1 THEN RETURN to_jsonb(current_state); END IF;
 IF current_state.epoch<>p_expected_epoch THEN
  RAISE EXCEPTION 'SYS_WRITE_EPOCH_CONFLICT' USING ERRCODE='40001';
 END IF;
 IF current_state.mode=p_mode THEN RETURN to_jsonb(current_state); END IF;
 UPDATE public.sys_write_control SET mode=p_mode,epoch=epoch+1,batch_id=p_batch_id,
  operator=p_operator,reason=p_reason,changed_at=clock_timestamp() WHERE singleton
  RETURNING * INTO current_state;
 INSERT INTO public.sys_write_control_log(mode,epoch,batch_id,operator,reason,changed_at)
  VALUES(current_state.mode,current_state.epoch,p_batch_id,p_operator,p_reason,current_state.changed_at);
 RETURN to_jsonb(current_state);
END $function$

CREATE OR REPLACE FUNCTION public.jxc_supply_opening_basis(doc jsonb, target_kind text, completed_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE p record; expected_type text; setting text; in_batch boolean; field text;
BEGIN
 expected_type:=CASE target_kind WHEN 'PURCHASE_ORDER' THEN 'OPENING_PURCHASE' WHEN 'SHIPMENT' THEN 'OPENING_TRANSIT' ELSE NULL END;
 IF expected_type IS NULL OR doc->>'opening_ref' IS NULL OR doc->>'cutoff_date' IS NULL OR doc->>'import_row_id' IS NULL THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
 SELECT r.normalized,r.target_type,r.target_id,b.id batch_id,b.status,b.import_type,b.cutoff_date,b.requested_by INTO p
 FROM sys_import_row r JOIN sys_import_batch b ON b.country_id=r.country_id AND b.id=r.batch_id
 JOIN sys_import_source s ON s.country_id=r.country_id AND s.row_id=r.id AND s.import_type=b.import_type AND s.source_key=r.source_key
 WHERE r.country_id=(doc->>'country_id')::bigint AND r.id=(doc->>'import_row_id')::bigint AND r.errors='[]'::jsonb;
 IF NOT FOUND OR p.import_type IS DISTINCT FROM expected_type OR p.cutoff_date IS DISTINCT FROM (doc->>'cutoff_date')::date
  OR (p.normalized->>'bookId')::bigint IS DISTINCT FROM (doc->>'book_id')::bigint
  OR p.normalized->>'refNo' IS DISTINCT FROM doc->>'opening_ref' OR (doc->>'biz_date')::date IS DISTINCT FROM p.cutoff_date
  OR (p.normalized->>'sourceDate')::date>p.cutoff_date OR (doc->>'created_by')::bigint IS DISTINCT FROM p.requested_by OR (doc->>'entity_id')::bigint IS DISTINCT FROM (SELECT entity_id FROM fin_book WHERE country_id=(doc->>'country_id')::bigint AND id=(doc->>'book_id')::bigint) THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
 setting:=current_setting('app.opening_import_batch',true);
 in_batch:=coalesce(setting ~ '^[1-9][0-9]{0,15}$',false) AND setting=p.batch_id::text AND p.status='VALIDATED' AND NOT completed_only;
 IF NOT in_batch AND NOT (p.status='COMPLETED' AND p.target_type=target_kind AND p.target_id=(doc->>'id')::bigint) THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
 IF target_kind='PURCHASE_ORDER' THEN
  IF (p.normalized->>'supplierId')::bigint IS DISTINCT FROM (doc->>'supplier_id')::bigint OR (p.normalized->>'entityId')::bigint IS DISTINCT FROM (doc->>'entity_id')::bigint OR p.normalized->>'currency' IS DISTINCT FROM doc->>'currency' OR (p.normalized->>'sourceDate')::date IS DISTINCT FROM (doc->>'order_date')::date OR (p.normalized->>'expectedDate')::date IS DISTINCT FROM (doc->>'expected_date')::date THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
 ELSE
  IF (p.normalized->>'carrierId')::bigint IS DISTINCT FROM (doc->>'carrier_id')::bigint OR (p.normalized->>'destWarehouseId')::bigint IS DISTINCT FROM (doc->>'dest_warehouse_id')::bigint OR p.normalized->>'transportMode' IS DISTINCT FROM doc->>'transport_mode' OR (p.normalized->>'sourceDate')::date IS DISTINCT FROM (doc->>'opening_source_date')::date THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
  FOR field IN SELECT unnest(CASE WHEN p.normalized->>'transportMode'='SEA' THEN ARRAY['vessel','voyage','blNo','containerNo','sealNo'] ELSE ARRAY['awbNo','flightNo'] END) LOOP
   IF field IN ('containerNo','sealNo') AND NOT in_batch THEN CONTINUE;END IF;
   IF p.normalized->>field IS DISTINCT FROM doc->>(CASE field WHEN 'blNo' THEN 'bl_no' WHEN 'containerNo' THEN 'current_container_no' WHEN 'sealNo' THEN 'current_seal_no' WHEN 'awbNo' THEN 'awb_no' WHEN 'flightNo' THEN 'flight_no' ELSE field END) THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
  END LOOP;
 END IF;
 RETURN p.normalized;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_supply_period_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE ignored text[];basis jsonb;head record;expected_total numeric;expected_qty numeric;expected_tax numeric;line_count integer;
BEGIN
 ignored:=CASE TG_TABLE_NAME WHEN 'pur_order' THEN ARRAY['status','version','approval_instance_id'] WHEN 'lgs_shipment' THEN ARRAY['status','version','actual_etd','actual_eta','current_container_no','current_seal_no'] WHEN 'lgs_delivery' THEN ARRAY['status','version','dispatched_at'] WHEN 'lgs_node' THEN ARRAY['version','corrected_by_id'] WHEN 'lgs_hold' THEN ARRAY['version','status'] WHEN 'lgs_discrepancy' THEN ARRAY['version','status','resolution','remark'] WHEN 'pur_domestic_receipt' THEN ARRAY['status','version'] WHEN 'pur_export_node' THEN ARRAY['status','version'] ELSE ARRAY['version'] END;
 IF TG_TABLE_NAME IN ('pur_order','lgs_shipment') AND (to_jsonb(NEW)->>'opening_ref' IS NOT NULL OR to_jsonb(OLD)->>'opening_ref' IS NOT NULL) THEN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_IMMUTABLE';END IF;
  -- Current container identifiers are mutable logistics progress; the initial source identifiers remain in the sealed row.
  basis:=jxc_supply_opening_basis(CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END,CASE TG_TABLE_NAME WHEN 'pur_order' THEN 'PURCHASE_ORDER' ELSE 'SHIPMENT' END);
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ignored)=(to_jsonb(OLD)-ignored) THEN RETURN NEW;END IF;
  IF TG_OP='UPDATE' THEN
   IF TG_TABLE_NAME<>'pur_order' OR (to_jsonb(NEW)-ARRAY['total_qty','total_amount','tax_amount']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['total_qty','total_amount','tax_amount']) OR current_setting('app.opening_import_batch',true) IS DISTINCT FROM (SELECT batch_id::text FROM sys_import_row WHERE country_id=NEW.country_id AND id=(to_jsonb(NEW)->>'import_row_id')::bigint) THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_IMMUTABLE';END IF;
   SELECT count(*),coalesce(sum(base_qty),0),coalesce(sum(amount),0),round(coalesce(sum(amount*tax_rate),0),4) INTO line_count,expected_qty,expected_total,expected_tax FROM pur_order_line WHERE country_id=NEW.country_id AND order_id=NEW.id;
   IF line_count<>jsonb_array_length(basis->'lines') OR (to_jsonb(NEW)->>'total_qty')::numeric<>expected_qty OR (to_jsonb(NEW)->>'total_amount')::numeric<>expected_total OR (to_jsonb(NEW)->>'tax_amount')::numeric<>expected_tax THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
  ELSIF TG_TABLE_NAME='pur_order' AND ((to_jsonb(NEW)->>'total_qty')::numeric<>0 OR (to_jsonb(NEW)->>'total_amount')::numeric<>0 OR (to_jsonb(NEW)->>'tax_amount')::numeric<>0 OR NEW.status<>'DRAFT') THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';
  ELSIF TG_TABLE_NAME='lgs_shipment' AND NEW.status<>'DRAFT' THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
  PERFORM jxc_assert_country_trade(NEW.country_id,NEW.biz_date);PERFORM jxc_assert_opening_cutoff_period(NEW.country_id,NEW.book_id,NEW.biz_date);RETURN NEW;
 END IF;
 -- The initial opening container has a technical active_from default, not a known entry instant.
 -- Closing it is a later native logistics fact; its actual country day must be an ordinary open period.
 IF TG_TABLE_NAME='lgs_container' AND TG_OP='UPDATE' THEN
  IF NEW.active_to IS DISTINCT FROM OLD.active_to THEN
  SELECT * INTO head FROM lgs_shipment WHERE country_id=OLD.country_id AND id=OLD.shipment_id;
  IF head.opening_ref IS NOT NULL AND OLD.biz_date=head.cutoff_date THEN
   basis:=jxc_supply_opening_basis(to_jsonb(head),'SHIPMENT',true);
   IF OLD.book_id IS DISTINCT FROM head.book_id
    OR OLD.container_no IS DISTINCT FROM basis->>'containerNo' OR OLD.seal_no IS DISTINCT FROM basis->>'sealNo'
    OR OLD.active_to IS NOT NULL OR NEW.active_to IS NULL OR NEW.version<>OLD.version+1
    OR (to_jsonb(NEW)-ARRAY['active_to','version']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['active_to','version']) THEN
    RAISE EXCEPTION 'SYS_IMPORT_SOURCE_IMMUTABLE';
   END IF;
   IF (NEW.active_to AT TIME ZONE (SELECT timezone FROM sys_country WHERE id=OLD.country_id))::date < head.cutoff_date THEN
    RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';
   END IF;
   PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,(NEW.active_to AT TIME ZONE (SELECT timezone FROM sys_country WHERE id=OLD.country_id))::date);
   RETURN NEW;
  END IF;
  END IF;
 END IF;
 IF TG_TABLE_NAME='lgs_container' AND TG_OP='INSERT' THEN
  SELECT * INTO head FROM lgs_shipment WHERE country_id=NEW.country_id AND id=NEW.shipment_id;
  IF head.opening_ref IS NOT NULL AND NEW.biz_date=head.cutoff_date THEN basis:=jxc_supply_opening_basis(to_jsonb(head),'SHIPMENT');IF NEW.container_no IS DISTINCT FROM basis->>'containerNo' OR NEW.seal_no IS DISTINCT FROM basis->>'sealNo' THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;PERFORM jxc_assert_country_trade(NEW.country_id,NEW.biz_date);PERFORM jxc_assert_opening_cutoff_period(NEW.country_id,NEW.book_id,NEW.biz_date);RETURN NEW;END IF;
 END IF;
 IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ignored)=(to_jsonb(OLD)-ignored) THEN RETURN NEW;END IF;
 IF TG_OP<>'INSERT' THEN PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.biz_date);END IF;
 IF TG_OP<>'DELETE' THEN PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,NEW.biz_date);RETURN NEW;END IF;RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_supply_source_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record; source record; po record;
BEGIN
 IF TG_TABLE_NAME='pur_domestic_receipt_line' THEN
  SELECT r.order_id,l.order_id actual_order,l.product_id INTO p FROM pur_domestic_receipt r JOIN pur_order_line l ON l.country_id=r.country_id WHERE r.country_id=NEW.country_id AND r.id=NEW.receipt_id AND l.id=NEW.order_line_id;
  IF NOT FOUND OR p.order_id<>p.actual_order OR p.product_id<>NEW.product_id THEN RAISE EXCEPTION 'PUR_RECEIPT_SOURCE_MISMATCH'; END IF;
 ELSIF TG_TABLE_NAME='pur_export_node_line' THEN
  SELECT r.order_line_id,r.product_id,d.book_id,d.entity_id INTO source FROM pur_domestic_receipt_line r JOIN pur_domestic_receipt d ON d.country_id=r.country_id AND d.id=r.receipt_id WHERE r.country_id=NEW.country_id AND r.id=NEW.receipt_line_id;
  SELECT book_id,entity_id INTO p FROM pur_export_node WHERE country_id=NEW.country_id AND id=NEW.export_node_id;
  IF source IS NULL OR source.order_line_id<>NEW.order_line_id OR source.product_id<>NEW.product_id OR source.book_id<>p.book_id OR source.entity_id<>p.entity_id THEN RAISE EXCEPTION 'PUR_EXPORT_SOURCE_MISMATCH'; END IF;
 ELSIF TG_TABLE_NAME='lgs_shipment_line' THEN
  IF NEW.source_type='EXPORT_NODE_LINE' THEN SELECT l.order_line_id,l.product_id,d.book_id,d.entity_id INTO source FROM pur_export_node_line l JOIN pur_export_node d ON d.country_id=l.country_id AND d.id=l.export_node_id WHERE l.country_id=NEW.country_id AND l.id=NEW.source_line_id;
  ELSIF NEW.source_type='OPENING_PURCHASE_LINE' THEN SELECT l.id AS order_line_id,l.product_id,d.book_id,d.entity_id INTO source FROM pur_order_line l JOIN pur_order d ON d.country_id=l.country_id AND d.id=l.order_id WHERE l.country_id=NEW.country_id AND l.id=NEW.source_line_id AND d.opening_ref IS NOT NULL AND d.id=NEW.po_id;
  ELSE SELECT l.order_line_id,l.product_id,d.book_id,d.entity_id INTO source FROM pur_domestic_receipt_line l JOIN pur_domestic_receipt d ON d.country_id=l.country_id AND d.id=l.receipt_id WHERE l.country_id=NEW.country_id AND l.id=NEW.source_line_id; END IF;
  SELECT book_id,entity_id INTO p FROM lgs_shipment WHERE country_id=NEW.country_id AND id=NEW.shipment_id;
  IF source IS NULL OR source.order_line_id<>NEW.po_line_id OR source.product_id<>NEW.product_id OR source.book_id<>p.book_id OR source.entity_id<>p.entity_id THEN RAISE EXCEPTION 'LGS_SHIPMENT_SOURCE_MISMATCH'; END IF;
 ELSIF TG_TABLE_NAME='lgs_delivery_line' THEN
  SELECT s.shipment_id,s.product_id,s.po_line_id INTO source FROM lgs_shipment_line s WHERE s.country_id=NEW.country_id AND s.id=NEW.shipment_line_id;
  SELECT shipment_id INTO p FROM lgs_delivery WHERE country_id=NEW.country_id AND id=NEW.delivery_id;
  IF source IS NULL OR source.shipment_id<>p.shipment_id OR source.product_id<>NEW.product_id OR source.po_line_id<>NEW.po_line_id THEN RAISE EXCEPTION 'LGS_DELIVERY_SOURCE_MISMATCH'; END IF;
 ELSIF TG_TABLE_NAME='lgs_receipt_line' THEN
  SELECT l.delivery_id,l.shipment_line_id,l.product_id,l.dispatch_qty INTO source FROM lgs_delivery_line l WHERE l.country_id=NEW.country_id AND l.id=NEW.delivery_line_id;
  SELECT delivery_id,status INTO p FROM lgs_receipt WHERE country_id=NEW.country_id AND id=NEW.receipt_id;
  IF source IS NULL OR source.delivery_id<>p.delivery_id OR source.shipment_line_id<>NEW.shipment_line_id OR source.product_id<>NEW.product_id OR source.dispatch_qty<>NEW.dispatch_qty THEN RAISE EXCEPTION 'LGS_RECEIPT_SOURCE_MISMATCH'; END IF;
  IF p.status='CONFIRMED' AND NEW.good_qty+NEW.damaged_qty+NEW.pending_inspect_qty+NEW.short_qty<>NEW.dispatch_qty THEN RAISE EXCEPTION 'LGS_RECEIPT_QTY_MISMATCH'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_transfer_header_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['status','version','shipped_at','received_at','closed_at','close_reason','difference_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','version','shipped_at','received_at','closed_at','close_reason','difference_id'])) THEN
  IF OLD.status<>'DRAFT' OR EXISTS(SELECT 1 FROM inv_transfer_line WHERE country_id=OLD.country_id AND transfer_id=OLD.id AND shipped_qty>0) THEN RAISE EXCEPTION 'transfer economic facts frozen';END IF;PERFORM jxc_assert_period_open(OLD.country_id,OLD.book_id,OLD.biz_date);
 END IF;
 IF TG_OP<>'DELETE' THEN
  IF TG_OP='INSERT' OR NEW.biz_date IS DISTINCT FROM OLD.biz_date OR NEW.book_id IS DISTINCT FROM OLD.book_id THEN PERFORM jxc_assert_period_open(NEW.country_id,NEW.book_id,NEW.biz_date);END IF;
  IF NEW.status='CLOSED' AND EXISTS(SELECT 1 FROM inv_transfer_line WHERE country_id=NEW.country_id AND transfer_id=NEW.id AND received_qty+loss_qty<>shipped_qty) THEN RAISE EXCEPTION 'unresolved transfer quantities cannot close';END IF;RETURN NEW;
 END IF;RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION public.jxc_transfer_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE t inv_transfer%ROWTYPE; c bigint; parent bigint;
BEGIN
 IF TG_OP='DELETE' THEN c:=OLD.country_id;parent:=OLD.transfer_id;ELSE c:=NEW.country_id;parent:=NEW.transfer_id;END IF;
 SELECT * INTO t FROM inv_transfer WHERE country_id=c AND id=parent FOR UPDATE;
 IF TG_OP<>'UPDATE' OR (to_jsonb(NEW)-ARRAY['shipped_qty','received_qty','loss_qty']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['shipped_qty','received_qty','loss_qty']) THEN
  IF t.status<>'DRAFT' THEN RAISE EXCEPTION 'transfer lines frozen outside draft';END IF;PERFORM jxc_assert_period_open(t.country_id,t.book_id,t.biz_date);
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.lgs_shipment_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record;basis jsonb;
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.country_id,NEW.shipment_id,NEW.source_type,NEW.source_line_id,NEW.po_id,NEW.po_line_id,NEW.product_id,NEW.base_qty,NEW.boxes,NEW.unit_weight,NEW.unit_volume) IS NOT DISTINCT FROM ROW(OLD.country_id,OLD.shipment_id,OLD.source_type,OLD.source_line_id,OLD.po_id,OLD.po_line_id,OLD.product_id,OLD.base_qty,OLD.boxes,OLD.unit_weight,OLD.unit_volume) THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.boxes,NEW.unit_weight,NEW.unit_volume) IS DISTINCT FROM ROW(OLD.boxes,OLD.unit_weight,OLD.unit_volume) THEN
  SELECT * INTO p FROM lgs_shipment WHERE country_id=OLD.country_id AND id=OLD.shipment_id;
  IF p.status<>'DRAFT' OR p.opening_ref IS NOT NULL THEN RAISE EXCEPTION 'BUSINESS_FACT_IMMUTABLE';END IF;
 END IF;
 IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM lgs_shipment WHERE country_id=OLD.country_id AND id=OLD.shipment_id;IF p.opening_ref IS NOT NULL THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_IMMUTABLE';END IF;END IF;
 SELECT * INTO p FROM lgs_shipment WHERE country_id=coalesce(NEW.country_id,OLD.country_id) AND id=coalesce(NEW.shipment_id,OLD.shipment_id);
 IF p.opening_ref IS NOT NULL THEN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_IMMUTABLE';END IF;
  basis:=jxc_supply_opening_basis(to_jsonb(p),'SHIPMENT');
  IF NEW.boxes IS NOT NULL OR NEW.unit_weight IS NOT NULL OR NEW.unit_volume IS NOT NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(basis->'lines') l WHERE l->>'sourceType'=NEW.source_type AND (l->>'sourceLineId')::bigint=NEW.source_line_id AND (l->>'baseQty')::numeric=NEW.base_qty) THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
  PERFORM jxc_assert_country_trade(p.country_id,p.biz_date);PERFORM jxc_assert_opening_cutoff_period(p.country_id,p.book_id,p.cutoff_date);RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM lgs_shipment WHERE country_id=OLD.country_id AND id=OLD.shipment_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);END IF;IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM lgs_shipment WHERE country_id=NEW.country_id AND id=NEW.shipment_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);RETURN NEW;END IF;RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION public.pur_order_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p record;basis jsonb;expected jsonb;
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.country_id,NEW.order_id,NEW.line_no,NEW.product_id,NEW.unit,NEW.base_unit,NEW.factor,NEW.qty,NEW.base_qty,NEW.unit_price,NEW.amount,NEW.tax_rate,NEW.delivery_date) IS NOT DISTINCT FROM ROW(OLD.country_id,OLD.order_id,OLD.line_no,OLD.product_id,OLD.unit,OLD.base_unit,OLD.factor,OLD.qty,OLD.base_qty,OLD.unit_price,OLD.amount,OLD.tax_rate,OLD.delivery_date) THEN RETURN NEW;END IF;
 IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM pur_order WHERE country_id=OLD.country_id AND id=OLD.order_id;IF p.opening_ref IS NOT NULL THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_IMMUTABLE';END IF;END IF;
 SELECT * INTO p FROM pur_order WHERE country_id=coalesce(NEW.country_id,OLD.country_id) AND id=coalesce(NEW.order_id,OLD.order_id);
 IF p.opening_ref IS NOT NULL THEN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_IMMUTABLE';END IF;
  basis:=jxc_supply_opening_basis(to_jsonb(p),'PURCHASE_ORDER');expected:=basis->'lines'->(NEW.line_no-1);
  IF expected IS NULL OR (expected->>'productId')::bigint IS DISTINCT FROM NEW.product_id OR expected->>'unit' IS DISTINCT FROM NEW.unit OR (expected->>'qty')::numeric IS DISTINCT FROM NEW.qty OR (expected->>'unitPrice')::numeric IS DISTINCT FROM NEW.unit_price OR (expected->>'taxRate')::numeric IS DISTINCT FROM NEW.tax_rate OR expected->>'baseUnit' IS DISTINCT FROM NEW.base_unit OR (expected->>'factor')::numeric IS DISTINCT FROM NEW.factor OR (expected->>'baseQty')::numeric IS DISTINCT FROM NEW.base_qty OR NEW.amount<>round(NEW.qty*NEW.unit_price,4) THEN RAISE EXCEPTION 'SYS_IMPORT_SOURCE_MISMATCH';END IF;
  PERFORM jxc_assert_country_trade(p.country_id,p.biz_date);PERFORM jxc_assert_opening_cutoff_period(p.country_id,p.book_id,p.cutoff_date);RETURN NEW;
 END IF;
 IF TG_OP<>'INSERT' THEN SELECT * INTO p FROM pur_order WHERE country_id=OLD.country_id AND id=OLD.order_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);END IF;IF TG_OP<>'DELETE' THEN SELECT * INTO p FROM pur_order WHERE country_id=NEW.country_id AND id=NEW.order_id;PERFORM jxc_assert_period_open(p.country_id,p.book_id,p.biz_date);RETURN NEW;END IF;RETURN OLD;
END $function$
